/// RED (round-3 finding 2.3): the fork CASCADE's terminal hard delete
/// releases the max_streams slot — not only the direct delete path.
/// Observed through the quota registry on the deployment tenant: the
/// probe reservation at a cap of 1 succeeds only if BOTH the fork's
/// own delete and the cascaded source tombstone released.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn fork_cascade_hard_delete_releases_the_stream_slot() {
    let (state, addr) = http_rig(mem()).await;
    let ct = ("content-type", "application/json");
    let auth = ("authorization", "Bearer dst-internal-token");
    // Source with one record, then a fork of it.
    let (st, _, _) = hreq(
        addr,
        "PUT",
        "/v1/stream/fcq-src",
        &[ct, auth],
        br#"[{"i":0}]"#,
    )
    .await;
    assert!(st == 200 || st == 201);
    let (_, h, _) = hreq(addr, "GET", "/v1/stream/fcq-src", &[auth], b"").await;
    let boundary = h.get("stream-next-offset").cloned().unwrap_or_default();
    let fork = [
        ct,
        auth,
        ("stream-forked-from", "fcq-src"),
        ("stream-fork-offset", boundary.as_str()),
    ];
    let (st, _, b) = hreq(addr, "PUT", "/v1/stream/fcq-child", &fork, b"").await;
    assert!(
        st == 200 || st == 201,
        "fork create: {st} {}",
        String::from_utf8_lossy(&b)
    );
    // Track + seed the deployment project at the CURRENT live count.
    let tenant = state.deployment.deployment_tenant().clone();
    let q = crate::project_policy::ProjectQuotas::default();
    let _ = state.quotas.admit(&tenant, &q, crate::shard::now_ms());
    let seed_q = crate::project_policy::ProjectQuotas {
        max_streams: 100,
        ..Default::default()
    };
    let live0 = 2u64; // fcq-src + fcq-child
    drop(
        state
            .quotas
            .reserve_stream(&tenant, &seed_q, Some(live0))
            .expect("seed"),
    );
    // Soft delete the source (fork retains it): still counts.
    let (st, _, _) = hreq(addr, "DELETE", "/v1/stream/fcq-src", &[auth], b"").await;
    assert!(st == 200 || st == 204, "source delete: {st}");
    // Delete the fork: its own hard delete releases one slot AND the
    // cascade tombstones the retained source — releasing the second.
    let (st, _, _) = hreq(addr, "DELETE", "/v1/stream/fcq-child", &[auth], b"").await;
    assert!(st == 200 || st == 204, "fork delete: {st}");
    // Probe: count must be back to 0 — a cap of 1 admits.
    let probe_q = crate::project_policy::ProjectQuotas {
        max_streams: 1,
        ..Default::default()
    };
    match state.quotas.reserve_stream(&tenant, &probe_q, None) {
        Ok(Some(r)) => drop(r),
        other => panic!(
            "cascade must release the retained source's slot (count stuck above 0): {:?}",
            other.err()
        ),
    }
    engine_shutdown(&state).await;
}

/// Quota transition: max_streams 0 (unlimited) -> nonzero seeds from
/// the catalog at the FIRST limited create, counting what unlimited
/// mode already made.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn max_streams_transition_seeds_from_reality() {
    let scopes = "streams.create streams.records.append streams.records.read";
    let unlimited = crate::project_policy::ProjectQuotas::default();
    let (state, addr, auth) = quota_rig("tr", scopes, unlimited).await;
    let a = ("authorization", auth.as_str());
    let ekey = ("prisma-encryption-key", PRISMA_KEY);
    for i in 0..3 {
        let (st, _, _) = preq(
            addr,
            "PUT",
            &format!("/v1/streams/t{i}"),
            &[ekey, a],
            br#"{"format":{"kind":"json"}}"#,
        )
        .await;
        assert_eq!(st, 201);
    }
    // Policy update: the limit arrives BELOW the existing count.
    let pid = crate::tenant::ProjectId::new("proj-q-tr").unwrap();
    let mut projects = std::collections::HashMap::new();
    projects.insert(
        pid.clone(),
        crate::project_policy::ProjectPolicy {
            project_id: pid,
            workspace_id: crate::tenant::WorkspaceId::new("ws-q-tr").unwrap(),
            cell_id: std::sync::Arc::from("test-cell"),
            project_policy_version: 2,
            ownership_version: 1,
            status: crate::project_policy::ProjectStatus::Active,
            quotas: crate::project_policy::ProjectQuotas {
                max_streams: 2,
                ..Default::default()
            },
        },
    );
    state
        .auth
        .publish_policies(crate::project_policy::PolicySnapshot {
            projects,
            fetched_at_unix: crate::shard::now_ms() / 1000,
            feed_version: 2,
        })
        .unwrap();
    // The next create seeds count=3 from the catalog and refuses.
    let (st, _, b) = preq(
        addr,
        "PUT",
        "/v1/streams/t3",
        &[ekey, a],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(
        st,
        429,
        "re-enabled limit must seed from the real count: {st} {}",
        String::from_utf8_lossy(&b)
    );
    engine_shutdown(&state).await;
}

#[test]
fn jwks_kid_lifecycle_rules() {
    const PUB: &str = include_str!("fixtures/mt-test-rsa.pub.pem");
    let svc = crate::auth::AuthService::new(
        crate::auth::AuthMode::Enforce,
        "https://auth.prisma.io".into(),
        "test-cell",
    )
    .unwrap();
    let key = |pem: &str| crate::auth::JwksKey {
        alg: jsonwebtoken::Algorithm::RS256,
        key: jsonwebtoken::DecodingKey::from_rsa_pem(pem.as_bytes()).unwrap(),
        fp: crate::auth::key_fp(pem.as_bytes()),
    };
    let snap = |ver: u64, kids: &[&str]| {
        let mut keys = std::collections::HashMap::new();
        for k in kids {
            keys.insert(k.to_string(), key(PUB));
        }
        crate::auth::JwksSnapshot {
            keys,
            fetched_at_unix: 1_000_000,
            feed_version: ver,
        }
    };
    // Overlap rotation: {A} -> {A,B} -> {B}: all accepted.
    svc.publish_jwks(snap(1, &["kid-a"])).unwrap();
    svc.publish_jwks(snap(2, &["kid-a", "kid-b"])).unwrap();
    svc.publish_jwks(snap(3, &["kid-b"])).unwrap();
    // Identical generation replay: accepted.
    svc.publish_jwks(snap(3, &["kid-b"])).unwrap();
    // Same generation, different key SET: refused.
    assert!(
        svc.publish_jwks(snap(3, &["kid-b", "kid-c"])).is_err(),
        "same generation with a different key set must refuse"
    );
    // Retired kid reintroduced at a HIGHER generation: refused.
    assert!(
        svc.publish_jwks(snap(4, &["kid-a", "kid-b"])).is_err(),
        "a retired kid must never return"
    );
    // Same kid, DIFFERENT key material: refused. (A second RSA key is
    // synthesized by fingerprint tampering at the type level being
    // impossible — so use the ed25519 test key's PEM as different
    // material under the same kid.)
    let mut keys = std::collections::HashMap::new();
    let mut k = key(PUB);
    k.fp = crate::auth::key_fp(b"different-material");
    keys.insert("kid-b".to_string(), k);
    let r = svc.publish_jwks(crate::auth::JwksSnapshot {
        keys,
        fetched_at_unix: 1_000_000,
        feed_version: 5,
    });
    assert!(r.is_err(), "kid rebound to different material must refuse");
    // Fresh kid at a new generation still works (rotation continues).
    svc.publish_jwks(snap(6, &["kid-b", "kid-d"])).unwrap();
}

/// Round-3 finding (feeds): an entry ADDED under an already-published
/// generation is refused by the generation digest — per-ID checks
/// alone cannot see it.
#[test]
fn same_feed_generation_cannot_gain_entries() {
    let svc = crate::auth::AuthService::new(
        crate::auth::AuthMode::Enforce,
        "https://auth.prisma.io".into(),
        "test-cell",
    )
    .unwrap();
    let proj = |ids: &[&str]| {
        let mut m = std::collections::HashMap::new();
        for id in ids {
            let pid = crate::tenant::ProjectId::new(id).unwrap();
            m.insert(
                pid.clone(),
                crate::project_policy::ProjectPolicy {
                    project_id: pid,
                    workspace_id: crate::tenant::WorkspaceId::new("ws-g").unwrap(),
                    cell_id: std::sync::Arc::from("test-cell"),
                    project_policy_version: 1,
                    ownership_version: 1,
                    status: crate::project_policy::ProjectStatus::Active,
                    quotas: crate::project_policy::ProjectQuotas::default(),
                },
            );
        }
        crate::project_policy::PolicySnapshot {
            projects: m,
            fetched_at_unix: 1_000_000,
            feed_version: 9,
        }
    };
    svc.publish_policies(proj(&["proj-ga"])).unwrap();
    // Identical replay of generation 9: fine.
    svc.publish_policies(proj(&["proj-ga"])).unwrap();
    // Generation 9 grows a NEW project: refused.
    assert!(
        svc.publish_policies(proj(&["proj-ga", "proj-gb"])).is_err(),
        "an entry added under a published generation must refuse"
    );
}

/// RED (round-3 hardening): an unknown-kid nudge fired BETWEEN two
/// refresher iterations must not be lost. notify_one stores a permit
/// for the next waiter; notify_waiters does not — the nudge
/// evaporated and the rotated key waited out the polling interval.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn kid_nudge_fired_before_the_waiter_is_not_lost() {
    let svc = crate::auth::AuthService::new(
        crate::auth::AuthMode::Enforce,
        "https://auth.prisma.io".into(),
        "test-cell",
    )
    .unwrap();
    assert!(svc.request_kid_refresh(), "the nudge fires");
    // The refresher arrives LATE: the stored permit must wake it.
    tokio::time::timeout(
        std::time::Duration::from_millis(500),
        svc.kid_wakeup.notified(),
    )
    .await
    .expect("a pre-fired nudge must wake a late waiter (permit stored)");
}

// ---- #270 hub terminal state machine (Søren review F1+F4) ----------
// Red-first against 6843b8de: the pump marked a genuinely CLOSED hub
// dead in the same synchronous cleanup, so notified subscribers woke
// into Dead and dropped the final batch and sealed control; catch-up
// never conveyed upToDate.

/// Drive one hub SSE subscriber over raw TCP and collect frames until
/// `done(acc)` or body end or deadline. Returns (accumulated text,
/// body_ended). Body end = the chunked terminal ("0\r\n\r\n") — an
/// HTTP/1 keep-alive server ends the BODY without closing the TCP
/// socket — or a raw EOF.
async fn hub_sse_collect(
    sck: &mut tokio::net::TcpStream,
    deadline_secs: u64,
    done: impl Fn(&str) -> bool,
) -> (String, bool) {
    use tokio::io::AsyncReadExt;
    let mut buf = vec![0u8; 8192];
    let mut acc: Vec<u8> = Vec::new();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(deadline_secs);
    while std::time::Instant::now() < deadline {
        let text = String::from_utf8_lossy(&acc).to_string();
        if text.ends_with("0\r\n\r\n") {
            return (text, true);
        }
        if done(&text) {
            return (text, false);
        }
        let n = match tokio::time::timeout(std::time::Duration::from_secs(1), sck.read(&mut buf))
            .await
        {
            Ok(r) => r.expect("sse read"),
            Err(_) => continue,
        };
        if n == 0 {
            return (String::from_utf8_lossy(&acc).to_string(), true);
        }
        acc.extend_from_slice(&buf[..n]);
    }
    (String::from_utf8_lossy(&acc).to_string(), false)
}

async fn hub_sse_connect(addr: std::net::SocketAddr, name: &str) -> tokio::net::TcpStream {
    use tokio::io::AsyncWriteExt;
    let mut sck = tokio::net::TcpStream::connect(addr).await.unwrap();
    let req = format!(
        "GET /v1/streams/{name}/records:sse HTTP/1.1\r\nhost: x\r\ncontent-length: 0\r\nprisma-encryption-key: {PRISMA_KEY}\r\n\r\n"
    );
    sck.write_all(req.as_bytes()).await.unwrap();
    sck
}

/// Boot a rig, create the stream, and return a HUB subscriber. Post
/// #274/F8 the FIRST subscriber rides the direct path, so a PROMOTER
/// connection is opened (kept alive via the returned socket) and the
/// returned test subscriber is the SECOND — the one on the hub.
async fn hub_rig_stream(
    name: &str,
) -> (
    Arc<crate::http::AppState>,
    std::net::SocketAddr,
    tokio::net::TcpStream,
    tokio::net::TcpStream,
) {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        &format!("/v1/streams/{name}"),
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let mut promoter = hub_sse_connect(addr, name).await;
    let (acc, _) = hub_sse_collect(&mut promoter, 8, |t| t.contains("upToDate")).await;
    assert!(acc.contains("upToDate"), "promoter joins direct:\n{acc}");
    let sck = hub_sse_connect(addr, name).await;
    (state, addr, promoter, sck)
}

async fn hub_append(addr: std::net::SocketAddr, name: &str, body: &str) {
    let (st, _, _) = preq(
        addr,
        "POST",
        &format!("/v1/streams/{name}/records"),
        &[("prisma-encryption-key", PRISMA_KEY)],
        body.as_bytes(),
    )
    .await;
    assert!(st == 200 || st == 204, "append {st}");
}

