/// Replaces `hub_no_up_to_date_while_pump_holds_backlog`: upToDate is
/// a statement about the DURABLE stream — while durable records exist
/// that the feed has not yet driven, no upToDate may be claimed. The
/// drive is held at its failpoint with a durable backlog behind it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_no_up_to_date_while_backlog_is_undriven() {
    let store = mem();
    let (_state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfhb",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let mut sck = lf_connect(addr, "lfhb", "").await;
    let (a, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(a.contains("\"upToDate\":true"), "parks at the tail:\n{a}");

    crate::failpoints::arm(crate::failpoints::Fp::SseFeedBeforeDrive, "lfhb");
    hub_append_lf(addr, "lfhb", r#"{"b":0}"#).await;
    hub_append_lf(addr, "lfhb", r#"{"b":1}"#).await;
    wait_parked(crate::failpoints::Fp::SseFeedBeforeDrive, "lfhb", 1).await;
    // The backlog is durable and UNDRIVEN: no data, and above all no
    // upToDate claim, may appear.
    let (held, eof) = hub_sse_collect(&mut sck, 2, |_| false).await;
    assert!(!eof, "no disconnect while the drive is held:\n{held}");
    assert!(
        !held.contains("\"upToDate\":true"),
        "upToDate claimed over an undriven durable backlog:\n{held}"
    );
    assert!(
        !held.contains("event: data"),
        "no data can flow while the drive is held:\n{held}"
    );
    crate::failpoints::release(crate::failpoints::Fp::SseFeedBeforeDrive, "lfhb");
    let (t, eof2) = hub_sse_collect(&mut sck, 10, |t| lf_record_and_status(t, "\"b\":1")).await;
    assert!(!eof2, "released drive keeps the session open:\n{t}");
    for n in ["\"b\":0", "\"b\":1"] {
        assert_eq!(t.matches(n).count(), 1, "{n} exactly once:\n{t}");
    }
    let last_data = t.rfind("\"b\":1").expect("frontier record");
    let utd = t.find("\"upToDate\":true").expect("honest status");
    assert!(
        utd > last_data,
        "the resumed upToDate must FOLLOW the drained backlog:\n{t}"
    );
}

/// Replaces `hub_prepared_batch_must_not_carry_stale_up_to_date`: a
/// late attacher draining the retained ring while newer durable
/// records exist must not see upToDate until it truly reaches the
/// frontier — retained batches can never carry a stale claim
/// (LiveFeed record frames are structurally bare; this pins the
/// SESSION's status honesty over the ring-drain path).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_late_attach_never_claims_stale_up_to_date() {
    let store = mem();
    let (_state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfst",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfst", r#"{"s":0}"#).await;
    let mut s1 = lf_connect(addr, "lfst", "").await;
    let (a1, _) = hub_sse_collect(&mut s1, 8, |t| t.contains("upToDate")).await;
    assert!(a1.contains("\"s\":0"));

    // s2 attaches (shared: the ring retains from here) but is HELD
    // between attach and session start while the stream moves on.
    crate::failpoints::arm(crate::failpoints::Fp::SseFeedAfterSubscribe, "lfst");
    let mut s2 = lf_connect(addr, "lfst", "?cursor=beginning").await;
    wait_parked(crate::failpoints::Fp::SseFeedAfterSubscribe, "lfst", 1).await;
    hub_append_lf(addr, "lfst", r#"{"s":1}"#).await;
    hub_append_lf(addr, "lfst", r#"{"s":2}"#).await;
    // s1 drains the new records — the retained ring now holds batches
    // prepared while s2 was parked.
    let (d1, _) = hub_sse_collect(&mut s1, 10, |t| lf_record_and_status(t, "\"s\":2")).await;
    assert!(d1.contains("\"s\":2"));
    crate::failpoints::release(crate::failpoints::Fp::SseFeedAfterSubscribe, "lfst");

    let (a2, eof) = hub_sse_collect(&mut s2, 10, |t| lf_record_and_status(t, "\"s\":2")).await;
    assert!(!eof, "late attach must complete in place:\n{a2}");
    for i in 0..3u64 {
        let needle = format!("\"s\":{i}");
        assert_eq!(
            a2.matches(&needle).count(),
            1,
            "{needle} exactly once:\n{a2}"
        );
    }
    let last_data = a2.rfind("\"s\":2").expect("frontier record");
    let first_utd = a2.find("\"upToDate\":true").expect("status");
    assert!(
        first_utd > last_data,
        "upToDate claimed before the frontier record was delivered:\n{a2}"
    );
}

/// Replaces `hub_oversized_event_delivered_via_uncached_catchup` for
/// the LiveFeed posture. Singleton: an over-ring record is delivered
/// IN PLACE (solo drives retain nothing). Shared: the uncached
/// publication floors the ring — parked subscribers take the TYPED
/// lag disconnect (no terminal, no loss) and a durable resume from
/// their emitted cursor delivers the record exactly once. That
/// disconnect-and-resume trade (vs the hub's in-place uncached
/// catch-up) is the documented bounded-memory design.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_oversized_record_solo_in_place_shared_resumes_durably() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    // Tiny feed ring: a 64-KiB record can never be retained.
    state.livefeed.set_ring_bytes(4096);
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfbig2",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let big = format!(r#"{{"big":"{}"}}"#, "y".repeat(64 * 1024));

    // SINGLETON: over-ring record delivered in place, no disconnect.
    let mut s1 = lf_connect(addr, "lfbig2", "").await;
    let (a, _) = hub_sse_collect(&mut s1, 8, |t| t.contains("upToDate")).await;
    assert!(a.contains("upToDate"));
    hub_append_lf(addr, "lfbig2", &big).await;
    let (solo, eof) =
        hub_sse_collect(&mut s1, 10, |t| lf_record_and_status(t, "\"big\":\"yy")).await;
    assert!(!eof, "solo oversized delivery stays in place:\n…");
    assert_eq!(
        solo.matches("\"big\":\"").count(),
        1,
        "oversized exactly once"
    );

    // SHARED: the second oversized publication goes uncached; both
    // subscribers take a RESUMABLE EOF (the typed reason is
    // server-side only — counter + log; no wire error control, NO
    // terminal) and resume durably with no gap and no duplicate.
    let mut s2 = lf_connect(addr, "lfbig2", "").await;
    let (b, _) = hub_sse_collect(&mut s2, 8, |t| t.contains("upToDate")).await;
    let cur2 = last_next_cursor(&b);
    let cur1 = last_next_cursor(&solo);
    hub_append_lf(addr, "lfbig2", &big).await;
    for (n, (sck, cur)) in [(1, (&mut s1, cur1)), (2, (&mut s2, cur2))] {
        let (tail, eof) = hub_sse_collect(sck, 10, |_| false).await;
        assert!(
            eof,
            "sub{n}: uncached publication takes the typed disconnect"
        );
        assert!(
            !tail.contains("\"sealed\":true"),
            "sub{n}: a lag disconnect is never a terminal:\n{tail}"
        );
        let mut resumed = lf_connect(addr, "lfbig2", &format!("?cursor={cur}")).await;
        let (r, eof2) = hub_sse_collect(&mut resumed, 10, |t| {
            lf_record_and_status(t, "\"big\":\"yy")
        })
        .await;
        assert!(!eof2, "sub{n}: the resume completes in place:\n…");
        assert_eq!(
            r.matches("\"big\":\"").count(),
            1,
            "sub{n}: the oversized record arrives exactly once on resume"
        );
    }
}

/// Replaces `hub_global_cap_exhaustion_goes_uncached_but_delivers` for
/// the LiveFeed posture: with the process retention budget exhausted,
/// a shared feed's publication goes UNCACHED — parked subscribers get
/// a resumable EOF (typed reason server-side only; no terminal, no
/// loss) and, once budget exists again, resume durably with no gap
/// and no duplicate.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_budget_exhaustion_publishes_uncached_and_resumes() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfcap",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfcap", r#"{"c":0}"#).await;
    let mut s1 = lf_connect(addr, "lfcap", "").await;
    let (a1, _) = hub_sse_collect(&mut s1, 8, |t| t.contains("upToDate")).await;
    let cur1 = last_next_cursor(&a1);
    let mut s2 = lf_connect(addr, "lfcap", "").await;
    let (a2, _) = hub_sse_collect(&mut s2, 8, |t| t.contains("upToDate")).await;
    let cur2 = last_next_cursor(&a2);

    // Exhaust the process retention budget, then publish.
    let held = state.livefeed.budget().exhaust_for_test();
    hub_append_lf(addr, "lfcap", r#"{"c":1}"#).await;
    let mut cursors = Vec::new();
    for (n, (sck, cur)) in [(1, (&mut s1, cur1)), (2, (&mut s2, cur2))] {
        let (tail, eof) = hub_sse_collect(sck, 10, |_| false).await;
        assert!(
            eof,
            "sub{n}: an uncached publication takes the typed disconnect:\n{tail}"
        );
        assert!(
            !tail.contains("\"sealed\":true"),
            "sub{n}: never a terminal:\n{tail}"
        );
        cursors.push((n, cur));
    }
    // Budget returns; both resumes deliver the record exactly once.
    state.livefeed.budget().release_for_test(held);
    for (n, cur) in cursors {
        let mut resumed = lf_connect(addr, "lfcap", &format!("?cursor={cur}")).await;
        let (r, eof) =
            hub_sse_collect(&mut resumed, 10, |t| lf_record_and_status(t, "\"c\":1")).await;
        assert!(!eof, "sub{n}: the resume completes in place:\n{r}");
        assert_eq!(
            r.matches("\"c\":1").count(),
            1,
            "sub{n}: the record arrives exactly once on resume:\n{r}"
        );
    }
}

/// Round-10e review (red): a FORK's materialized partial record is a
/// customer record the child persists — it must satisfy the
/// per-record ceiling BEFORE any fork lifecycle work becomes durable.
/// The source record predates the ceiling ("created under a different
/// profile"); the oversized partial must refuse the fork with NO
/// externally visible child, and a compliant partial must still work.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn fork_materialized_partial_respects_the_record_ceiling() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let ct = [("content-type", "text/plain")];
    // The source record is created BEFORE the ceiling exists.
    let big = "x".repeat(8 * 1024);
    let (st, _, _) = hreq(addr, "PUT", "/v1/stream/fbig", &ct, big.as_bytes()).await;
    assert!(st == 200 || st == 201, "source create {st}");
    state.admission.set_record_ceiling(4096);
    // An oversized materialized partial (6000 > 4096): refused, and
    // the child never becomes externally visible.
    let (st, _, body) = hreq(
        addr,
        "PUT",
        "/v1/stream/fbig-child",
        &[
            ("content-type", "text/plain"),
            ("stream-forked-from", "/v1/stream/fbig"),
            ("stream-fork-offset", "0000000000000000_0000000000000000"),
            ("stream-fork-sub-offset", "6000"),
        ],
        b"",
    )
    .await;
    assert_eq!(st, 413, "{}", String::from_utf8_lossy(&body));
    assert!(
        String::from_utf8_lossy(&body).contains("record_too_large"),
        "typed refusal:\n{}",
        String::from_utf8_lossy(&body)
    );
    let (st, _, _) = hreq(addr, "GET", "/v1/stream/fbig-child", &[], b"").await;
    assert_eq!(st, 404, "no child may survive the refused fork");
    // A compliant partial still forks.
    let (st, _, body) = hreq(
        addr,
        "PUT",
        "/v1/stream/fbig-child2",
        &[
            ("content-type", "text/plain"),
            ("stream-forked-from", "/v1/stream/fbig"),
            ("stream-fork-offset", "0000000000000000_0000000000000000"),
            ("stream-fork-sub-offset", "1000"),
        ],
        b"",
    )
    .await;
    assert_eq!(st, 201, "{}", String::from_utf8_lossy(&body));
}

/// Two-instance rig: a full instance over the shared store with the
/// complete 2-bit shard prefix code, so segment routes split across
/// shards that can be owned by different instances.
async fn http_rig_owner(
    store: Arc<dyn ObjectStore>,
    instance: &str,
) -> (Arc<crate::http::AppState>, std::net::SocketAddr) {
    http_rig_owner_at(store, instance, RigRuntime::first()).await
}

async fn http_rig_owner_at(
    store: Arc<dyn ObjectStore>,
    instance: &str,
    runtime: RigRuntime,
) -> (Arc<crate::http::AppState>, std::net::SocketAddr) {
    http_rig_build(
        store,
        runtime,
        HttpRigOptions {
            prefixes: ["00", "01", "10", "11"]
                .iter()
                .map(|s| s.to_string())
                .collect(),
            instance: Some(instance.to_string()),
            ..Default::default()
        },
    )
    .await
    .parts()
}

/// Round-10 two-instance groundwork (red): a subscriber landing on
/// the CHILD's owner streams the WHOLE lineage — the sealed
/// predecessor is read from ITS owner over the bounded internal
/// segment-scan surface, the live child locally. Before the
/// SpanReader split, LineageSource::build refused ANY lineage with a
/// foreign span (WrongOwner), so the child's owner could not serve a
/// split stream's history at all. The live tail must still be local:
/// remote ownership of the TAIL stays a typed WrongOwner cutoff.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_remote_sealed_predecessor_streams_through_owner() {
    let store = mem();
    let (state_a, addr_a) = http_rig_owner(store.clone(), "inst-a").await;
    let (state_b, addr_b) = http_rig_owner_at(store, "inst-b", RigRuntime::incarnation(1)).await;
    // History on A, then a split (parent seg0 seals, the child opens).
    let (st, _, _) = preq(
        addr_a,
        "PUT",
        "/v1/streams/xown",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr_a, "xown", r#"{"h":0}"#).await;
    hub_append_lf(addr_a, "xown", r#"{"h":1}"#).await;
    let sref = state_a.deployment.raw_adapter_sref("xown");
    let _ = crate::scaler3::execute_split(&state_a, &sref, 0, 0x8000_0000_0000_0000).await;
    for _ in 0..200 {
        state_a.registry.invalidate(&sref);
        let d = state_a.registry.get(&sref).await.unwrap().unwrap();
        if d.segments
            .as_ref()
            .is_some_and(|m| m.pending.is_none() && m.segments.len() > 1)
        {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }
    state_b.registry.invalidate(&sref);
    let desc = state_b.registry.get(&sref).await.unwrap().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    // The parent's shard belongs to A (an override on B + A's peer
    // URL); the child's shard differs, so B serves it itself. The
    // fixed stream name makes both routes deterministic.
    let p_parent = state_b.shards.prefix_for(&desc.segment_route_by_id(0));
    let p_child = state_b
        .shards
        .prefix_for(&desc.segment_route_by_id(child_seg));
    assert_ne!(
        p_parent, p_child,
        "pick a stream name whose parent/child routes differ"
    );
    // B's view of the fleet: both instances active; the parent's
    // shard is pinned to A, every other shard to B (explicit
    // overrides beat the rendezvous pick for determinism).
    state_b
        .ownership
        .set_ring_active(vec!["inst-a".to_string(), "inst-b".to_string()]);
    {
        for p in state_b.shards.prefixes().to_vec() {
            let owner = if p == p_parent { "inst-a" } else { "inst-b" };
            state_b.ownership.set_override(&p, owner);
        }
    }
    state_b.peer.set_peer("inst-a", &format!("http://{addr_a}"));
    // The successor record lands through B (B owns the child's shard;
    // its open fences A's copy of that shard).
    hub_append_lf(addr_b, "xown", r#"{"h":2}"#).await;

    // THE contract: a subscriber on B streams the whole lineage —
    // remote sealed parent, local live child — and parks live ON THE
    // LIVEFEED ENGINE. (The legacy lineage streamer also relays
    // remote reads, so delivery alone cannot distinguish the engines;
    // legacy dies at Stage 7 deletion, so the feed itself must carry
    // this session.)
    let mut sck = lf_connect(addr_b, "xown", "?cursor=beginning").await;
    let (acc, eof) = hub_sse_collect(&mut sck, 15, |t| lf_record_and_status(t, "\"h\":2")).await;
    assert!(
        !eof,
        "the child's owner must serve the split stream in place:\n{acc}"
    );
    assert!(
        state_b.livefeed.registry().len() >= 1,
        "the session must ride the LIVEFEED engine, not the legacy lineage fallback"
    );
    for i in 0..3u64 {
        let needle = format!("\"h\":{i}");
        assert_eq!(
            acc.matches(&needle).count(),
            1,
            "{needle} exactly once across the ownership boundary:\n{acc}"
        );
    }
    let last_data = acc.rfind("\"h\":2").expect("frontier record");
    let utd = acc.find("\"upToDate\":true").expect("status");
    assert!(
        utd > last_data,
        "honest upToDate after the full lineage:\n{acc}"
    );
    // Liveness on the local child after the remote catch-up.
    hub_append_lf(addr_b, "xown", r#"{"h":3}"#).await;
    let (tail, eof2) = hub_sse_collect(&mut sck, 10, |t| lf_record_and_status(t, "\"h\":3")).await;
    assert!(!eof2, "still live:\n{tail}");
    assert_eq!(tail.matches("\"h\":3").count(), 1);
    // Internal pages are UNBILLED on the serving owner: A relayed the
    // sealed parent's records but its read accumulator must not have
    // metered them (customer metering happens once, at B's external
    // body yield).
    assert_eq!(
        read_billing_sum(&state_a),
        (0, 0),
        "internal segment-scan pages must never meter customer reads"
    );

    // PEER OUTAGE: a fresh subscriber whose remote predecessor pages
    // cannot be fetched STALLS with bounded retries — no data, no
    // false terminal, no EOF — and RECOVERS in place the moment the
    // peer returns. The first subscriber must be gone first: its
    // feed's retained ring covers the whole lineage and would serve a
    // late attacher without touching the peer.
    drop(sck);
    for _ in 0..200 {
        if state_b.livefeed.registry().len() == 0 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    }
    assert_eq!(
        state_b.livefeed.registry().len(),
        0,
        "the feed tears down at zero"
    );
    state_b
        .peer
        .set_peer("inst-a", &"http://127.0.0.1:9".to_string());
    let mut down = lf_connect(addr_b, "xown", "?cursor=beginning").await;
    let (held, eof3) = hub_sse_collect(&mut down, 2, |_| false).await;
    assert!(!eof3, "a peer outage is a stall, not a disconnect:\n{held}");
    assert!(
        !held.contains("event: data") && !held.contains("\"sealed\":true"),
        "no data and no false terminal while the peer is down:\n{held}"
    );
    state_b.peer.set_peer("inst-a", &format!("http://{addr_a}"));
    let (rec, eof4) = hub_sse_collect(&mut down, 15, |t| lf_record_and_status(t, "\"h\":3")).await;
    assert!(!eof4, "recovery completes in place:\n{rec}");
    for i in 0..4u64 {
        let needle = format!("\"h\":{i}");
        assert_eq!(
            rec.matches(&needle).count(),
            1,
            "{needle} exactly once after peer recovery:\n{rec}"
        );
    }
}

/// Round-11.3: KEYED live reads (raw-key records:sse with routingKey)
/// ride LiveFeed across a split IN PLACE — product cursor vocabulary,
/// exactly-once delivery, no false terminal. (The singular raw SSE
/// surface is keyless by design; keyed live subscriptions live here.)
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_rawkey_records_sse_survives_split() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfrk",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let append_ka = |i: u64| async move {
        let (st, _, _) = preq(
            addr,
            "POST",
            "/v1/streams/lfrk/records",
            &[
                ("prisma-encryption-key", PRISMA_KEY),
                ("prisma-routing-key", "ka"),
            ],
            format!(r#"{{"r":{i}}}"#).as_bytes(),
        )
        .await;
        assert!(st == 200 || st == 204, "append {i}: {st}");
    };
    append_ka(0).await;
    let mut sck = lf_connect(addr, "lfrk", "?routingKey=ka").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("\"r\":0"), "keyed backlog:\n{acc0}");

    split_and_await(&state, "lfrk", 0).await;
    append_ka(1).await;
    let (acc1, eof1) = hub_sse_collect(&mut sck, 10, |t| lf_record_and_status(t, "\"r\":1")).await;
    assert!(!eof1, "keyed live rides the split in place:\n{acc1}");
    assert!(
        !acc1.contains("\"sealed\":true"),
        "no false terminal:\n{acc1}"
    );
    assert_eq!(acc1.matches("\"r\":1").count(), 1, "exactly once:\n{acc1}");
    // Resume from the emitted cursor: exactly the tail.
    let tok = last_next_cursor(&acc1);
    append_ka(2).await;
    let mut r2 = lf_connect(addr, "lfrk", &format!("?routingKey=ka&cursor={tok}")).await;
    let (a2, eof2) = hub_sse_collect(&mut r2, 10, |t| lf_record_and_status(t, "\"r\":2")).await;
    assert!(!eof2);
    assert!(
        a2.contains("\"r\":2") && !a2.contains("\"r\":1") && !a2.contains("\"r\":0"),
        "resume from the split cursor: exactly the tail:\n{a2}"
    );
}

/// Round-11.2 (red): the typed remote-span protocol across THREE
/// instances. Phase 1: a sealed predecessor whose owner MOVED follows
/// exactly ONE verified redirect (A answers 409 replay-to inst-c; C
/// serves). Phase 2: a redirect loop (C points back at A) is refused
/// with the typed cutoff — nonterminal EOF, no endless retry. Phase
/// 3: a predecessor that moves TO the reading instance is adopted
/// locally. Phase 4: a MOVED LIVE TAIL is never served from stale
/// state — typed WrongOwner cutoff at the read.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_owner_movement_one_redirect_and_typed_cutoffs() {
    let store = mem();
    let (state_a, addr_a) = http_rig_owner(store.clone(), "inst-a").await;
    let (state_b, addr_b) =
        http_rig_owner_at(store.clone(), "inst-b", RigRuntime::incarnation(1)).await;
    let (_state_c, addr_c) = http_rig_owner_at(store, "inst-c", RigRuntime::incarnation(2)).await;
    let (st, _, _) = preq(
        addr_a,
        "PUT",
        "/v1/streams/xmv",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr_a, "xmv", r#"{"h":0}"#).await;
    hub_append_lf(addr_a, "xmv", r#"{"h":1}"#).await;
    let sref = state_a.deployment.raw_adapter_sref("xmv");
    let _ = crate::scaler3::execute_split(&state_a, &sref, 0, 0x8000_0000_0000_0000).await;
    for _ in 0..200 {
        state_a.registry.invalidate(&sref);
        let d = state_a.registry.get(&sref).await.unwrap().unwrap();
        if d.segments
            .as_ref()
            .is_some_and(|m| m.pending.is_none() && m.segments.len() > 1)
        {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }
    state_b.registry.invalidate(&sref);
    let desc = state_b.registry.get(&sref).await.unwrap().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    let p_parent = state_b.shards.prefix_for(&desc.segment_route_by_id(0));
    let p_child = state_b
        .shards
        .prefix_for(&desc.segment_route_by_id(child_seg));
    assert_ne!(p_parent, p_child);
    let all = ["inst-a", "inst-b", "inst-c"].map(str::to_string).to_vec();
    state_b.ownership.set_ring_active(all.clone());
    {
        for p in state_b.shards.prefixes().to_vec() {
            let owner = if p == p_parent { "inst-a" } else { "inst-b" };
            state_b.ownership.set_override(&p, owner);
        }
    }
    {
        state_b.peer.set_peer("inst-a", &format!("http://{addr_a}"));
        state_b.peer.set_peer("inst-c", &format!("http://{addr_c}"));
    }
    hub_append_lf(addr_b, "xmv", r#"{"h":2}"#).await;
    let teardown = |state_b: Arc<crate::http::AppState>| async move {
        for _ in 0..300 {
            if state_b.livefeed.registry().len() == 0 {
                return;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        panic!("feed teardown stalled");
    };

    // PHASE 1 — one verified redirect: A no longer owns the parent
    // and names inst-c; C serves the pages.
    state_a.ownership.set_ring_active(all.clone());
    state_a
        .ownership
        .set_override(&p_parent.clone(), &"inst-c".to_string());
    {
        let mut sck = lf_connect(addr_b, "xmv", "?cursor=beginning").await;
        let (acc, eof) =
            hub_sse_collect(&mut sck, 15, |t| lf_record_and_status(t, "\"h\":2")).await;
        assert!(!eof, "redirected reads serve in place:\n{acc}");
        for i in 0..3u64 {
            let needle = format!("\"h\":{i}");
            assert_eq!(
                acc.matches(&needle).count(),
                1,
                "{needle} exactly once through the redirect:\n{acc}"
            );
        }
        drop(sck);
    }
    teardown(state_b.clone()).await;

    // PHASE 2 — redirect LOOP refused: C points the parent back at A.
    _state_c.ownership.set_ring_active(all.clone());
    _state_c
        .ownership
        .set_override(&p_parent.clone(), &"inst-a".to_string());
    let loops_before = crate::sse::auth::sse_stats::FEED_CUTOFF_REDIRECT_LOOP
        .load(std::sync::atomic::Ordering::Relaxed);
    {
        let mut sck = lf_connect(addr_b, "xmv", "?cursor=beginning").await;
        let (acc, eof) = hub_sse_collect(&mut sck, 15, |_| false).await;
        assert!(
            eof,
            "a redirect loop is a typed cutoff, not a stall:\n{acc}"
        );
        assert!(
            !acc.contains("event: data") && !acc.contains("\"sealed\":true"),
            "no data, no false terminal on the loop cutoff:\n{acc}"
        );
    }
    assert!(
        crate::sse::auth::sse_stats::FEED_CUTOFF_REDIRECT_LOOP
            .load(std::sync::atomic::Ordering::Relaxed)
            > loops_before,
        "the loop must be counted under its typed reason"
    );
    teardown(state_b.clone()).await;

    // PHASE 3 — the predecessor moves TO the reader: B now owns it
    // and adopts it locally.
    state_b
        .ownership
        .set_override(&p_parent.clone(), &"inst-b".to_string());
    {
        let mut sck = lf_connect(addr_b, "xmv", "?cursor=beginning").await;
        let (acc, eof) =
            hub_sse_collect(&mut sck, 15, |t| lf_record_and_status(t, "\"h\":2")).await;
        assert!(
            !eof,
            "a locally-adopted predecessor serves in place:\n{acc}"
        );
        assert_eq!(acc.matches("\"h\":0").count(), 1, "local adoption:\n{acc}");
        drop(sck);
    }
    teardown(state_b.clone()).await;

    // PHASE 4 — the LIVE TAIL moves away UNDER an established feed:
    // the next read takes the typed WrongOwner cutoff (nonterminal
    // EOF), never stale local serving. Sub1 establishes the feed
    // while B still owns the child; the move lands; sub2 joins the
    // SAME feed and its catch-up read hits the moved tail.
    let wrong_before = crate::sse::auth::sse_stats::FEED_CUTOFF_WRONG_OWNER
        .load(std::sync::atomic::Ordering::Relaxed);
    let mut sub1 = lf_connect(addr_b, "xmv", "?cursor=beginning").await;
    let (a1, _) = hub_sse_collect(&mut sub1, 15, |t| lf_record_and_status(t, "\"h\":2")).await;
    assert!(a1.contains("\"h\":2"), "sub1 established:\n{a1}");
    state_b
        .ownership
        .set_override(&p_child.clone(), &"inst-a".to_string());
    {
        let mut sub2 = lf_connect(addr_b, "xmv", "?cursor=beginning").await;
        let (acc, _) = hub_sse_collect(&mut sub2, 15, |t| t.contains("HTTP/1.1 409")).await;
        // Round-11.3: the connect-time answer is the TYPED routing
        // refusal (the gateway reroutes the retry; the product
        // translator renders the inner not_ring_owner as its 409
        // conflict) — never a legacy fallback, never data from stale
        // state, never a terminal.
        assert!(
            acc.contains("HTTP/1.1 409"),
            "a moved live tail at connect is the typed routing refusal:\n{acc}"
        );
        // Round-11.4 field finding: without Streams-Replay-To the
        // product translator renders an ownership bounce as the
        // non-retryable cursor_beyond_tail — SDKs rewind healthy
        // cursors and routers never learn the new owner. The refusal
        // must carry the routing signal and keep its ownership code.
        let lower = acc.to_ascii_lowercase();
        assert!(
            lower.contains("streams-replay-to: inst-a"),
            "the ownership refusal must name the owner for the router:\n{acc}"
        );
        assert!(
            !acc.contains("cursor_beyond_tail"),
            "an ownership bounce is never a cursor condition:\n{acc}"
        );
        assert!(
            !acc.contains("event: data") && !acc.contains("\"sealed\":true"),
            "no stale data, no terminal:\n{acc}"
        );
    }
    assert!(
        crate::sse::auth::sse_stats::FEED_CUTOFF_WRONG_OWNER
            .load(std::sync::atomic::Ordering::Relaxed)
            > wrong_before,
        "the moved tail must be counted under WrongOwner"
    );
    drop(sub1);
}

/// Round-11.6 (red): the certification-mode seal-publication delay.
/// STREAMS_CERT_SEALED_PUBLISH_DELAY_MS widens the close→publication
/// gap so the field seal-herd campaign can observe the two-step
/// window on a REAL release binary. The knob must actually hold the
/// publication open for the configured window — and the seal must
/// still complete (the delay is a wider gap, not a broken seal).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn certification_seal_publish_delay_widens_the_gap() {
    let store = mem();
    let (state, addr) = http_rig_owner(store, "inst-b").await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/xdelay",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "xdelay", r#"{"d":0}"#).await;
    state
        .cert_sealed_publish_delay_ms
        .store(600, std::sync::atomic::Ordering::Relaxed);
    let t0 = std::time::Instant::now();
    seal_ok(addr, "xdelay").await;
    let elapsed = t0.elapsed();
    assert!(
        elapsed >= std::time::Duration::from_millis(600),
        "the armed delay must hold the publication window open: {elapsed:?}"
    );
    // The seal COMPLETED (seal_ok asserted success); the delay is a
    // window, never a wedge. And it is one-shot per seal drive, not a
    // tax on every later read: a replay serves promptly.
    state
        .cert_sealed_publish_delay_ms
        .store(0, std::sync::atomic::Ordering::Relaxed);
    let t1 = std::time::Instant::now();
    let mut sck = lf_connect(addr, "xdelay", "?cursor=beginning").await;
    let (acc, _) = hub_sse_collect(&mut sck, 10, |t| t.contains("\"sealed\":true")).await;
    assert!(
        acc.contains("\"d\":0") && acc.contains("\"sealed\":true"),
        "sealed replay serves records + terminal:\n{acc}"
    );
    assert!(
        t1.elapsed() < std::time::Duration::from_secs(5),
        "reads after the seal are undelayed"
    );
}

/// Round-11.4 fleet finding (red): an ORPHANED pending transition —
/// the executor died between the durable intent and the publication
/// (a crash, a fence, an ownership move mid-merge) — starved the
/// WHOLE stream: every livefeed connect answered 503
/// segment_transition, and resume() was driven only by sessions,
/// which could no longer exist. The certification fleet wedged in
/// pending=merge with every instance refusing every connect. The
/// refusal must HELP the transition along (spawn the idempotent
/// resume) so retrying clients converge.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_pending_transition_connect_drives_resume() {
    let store = mem();
    let (state, addr) = http_rig_owner(store, "inst-b").await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/xpend",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    for i in 0..3 {
        hub_append_lf(addr, "xpend", &format!(r#"{{"q":{i}}}"#)).await;
    }
    // Enter the seal-to-publication gap, then ORPHAN it: the executor
    // dies with the intent durable and the publication never issued.
    crate::failpoints::arm_scaler_before_publish("xpend");
    let sref = state.deployment.raw_adapter_sref("xpend");
    let split = {
        let state = state.clone();
        let sref = sref.clone();
        tokio::spawn(async move {
            crate::scaler3::execute_split(&state, &sref, 0, 0x8000_0000_0000_0000).await
        })
    };
    let mut pending_seen = false;
    for _ in 0..400 {
        state.registry.invalidate(&sref);
        let d = state.registry.get(&sref).await.unwrap().unwrap();
        if d.segments.as_ref().is_some_and(|m| m.pending.is_some()) {
            pending_seen = true;
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }
    assert!(pending_seen, "the split must reach the durable-intent gap");
    split.abort();
    let _ = split.await;
    crate::failpoints::release_scaler_before_publish("xpend");
    // A retrying client must converge: the typed 503 is retryable
    // BECAUSE the refusal drives the resume. Without that, nothing
    // ever completes the transition and this loops 503 forever.
    let mut served = false;
    for _ in 0..80 {
        let mut sck = lf_connect(addr, "xpend", "?cursor=beginning").await;
        let (acc, _) = hub_sse_collect(&mut sck, 5, |t| {
            t.contains("HTTP/1.1 503") || t.contains("\"upToDate\":true")
        })
        .await;
        if acc.contains("\"upToDate\":true") {
            assert!(
                acc.contains("\"q\":0"),
                "records replay after resume:\n{acc}"
            );
            served = true;
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(250)).await;
    }
    assert!(
        served,
        "an orphaned pending transition must converge under client retries"
    );
}

/// Round-11.4 fleet finding (red): a PARKED live session at a shard
/// that loses ownership must be WOKEN by the engine close and take
/// the typed WrongOwner cutoff — resumable EOF, no terminal, no
/// stale serving. On the real fleet the loser's engine closes when
/// slatedb fencing surfaces (or a straggler request forces the
/// possession-yield), but begin_close woke no parked readers: the
/// certification harness held a moved-away session on keep-alives
/// for 40 s with the new owner already serving.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_parked_live_session_is_cut_off_by_engine_close() {
    let store = mem();
    let (state_b, addr_b) = http_rig_owner(store, "inst-b").await;
    let (st, _, _) = preq(
        addr_b,
        "PUT",
        "/v1/streams/xpark",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr_b, "xpark", r#"{"p":0}"#).await;
    let wrong_before = crate::sse::auth::sse_stats::FEED_CUTOFF_WRONG_OWNER
        .load(std::sync::atomic::Ordering::Relaxed);
    let mut sub = lf_connect(addr_b, "xpark", "?cursor=now").await;
    let (a0, eof0) = hub_sse_collect(&mut sub, 15, |t| t.contains("\"upToDate\":true")).await;
    assert!(
        a0.contains("\"upToDate\":true") && !eof0,
        "session parked at the live tail:\n{a0}"
    );
    // Ownership moves away; the loser's engine closes (fence). The
    // parked session must observe it WITHOUT any traffic.
    state_b
        .ownership
        .set_ring_active(["inst-a", "inst-b"].map(str::to_string).to_vec());
    {
        let ov = &state_b.ownership;
        for p in state_b.shards.prefixes().to_vec() {
            ov.set_override(&p, &"inst-a".to_string());
        }
    }
    let engines: Vec<_> = state_b.shards.engines();
    for e in engines {
        e.begin_close();
    }
    let (a1, eof1) = hub_sse_collect(&mut sub, 10, |_| false).await;
    assert!(
        eof1,
        "the parked session must take the cutoff, not keep-alive forever:\n{a1}"
    );
    assert!(
        !a1.contains("event: data") && !a1.contains("\"sealed\":true"),
        "no stale data, no terminal:\n{a1}"
    );
    assert!(
        crate::sse::auth::sse_stats::FEED_CUTOFF_WRONG_OWNER
            .load(std::sync::atomic::Ordering::Relaxed)
            > wrong_before,
        "the cutoff must be classified WrongOwner"
    );
    drop(sub);
    for _ in 0..300 {
        if state_b.livefeed.registry().len() == 0 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    }
    assert_eq!(state_b.livefeed.registry().len(), 0, "feed teardown");
}

/// Round-11.1 (red): a BLACKHOLED peer — TCP accepted, request read,
/// no response ever — must not suppress SSE keep-alives (the body
/// owns them), must not cancel other subscribers, must cancel its
/// in-flight page on final client drop (feed teardown), and must
/// recover in place when the peer returns.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_blackholed_peer_never_suppresses_heartbeats() {
    let store = mem();
    let (state_a, addr_a) = http_rig_owner(store.clone(), "inst-a").await;
    let (state_b, addr_b) = http_rig_owner_at(store, "inst-b", RigRuntime::incarnation(1)).await;
    // Fast keep-alives so the leg proves cadence in seconds.
    state_b.livefeed.set_heartbeat_ms(300);
    let (st, _, _) = preq(
        addr_a,
        "PUT",
        "/v1/streams/xbh",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr_a, "xbh", r#"{"h":0}"#).await;
    let sref = state_a.deployment.raw_adapter_sref("xbh");
    let _ = crate::scaler3::execute_split(&state_a, &sref, 0, 0x8000_0000_0000_0000).await;
    for _ in 0..200 {
        state_a.registry.invalidate(&sref);
        let d = state_a.registry.get(&sref).await.unwrap().unwrap();
        if d.segments
            .as_ref()
            .is_some_and(|m| m.pending.is_none() && m.segments.len() > 1)
        {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }
    state_b.registry.invalidate(&sref);
    let desc = state_b.registry.get(&sref).await.unwrap().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    let p_parent = state_b.shards.prefix_for(&desc.segment_route_by_id(0));
    let p_child = state_b
        .shards
        .prefix_for(&desc.segment_route_by_id(child_seg));
    assert_ne!(p_parent, p_child);
    state_b
        .ownership
        .set_ring_active(vec!["inst-a".to_string(), "inst-b".to_string()]);
    {
        for p in state_b.shards.prefixes().to_vec() {
            let owner = if p == p_parent { "inst-a" } else { "inst-b" };
            state_b.ownership.set_override(&p, owner);
        }
    }
    hub_append_lf(addr_b, "xbh", r#"{"h":1}"#).await;

    // The BLACKHOLE: accepts, reads the request, never answers.
    let hole = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let hole_addr = hole.local_addr().unwrap();
    let held: Arc<std::sync::Mutex<Vec<tokio::net::TcpStream>>> = Arc::new(Default::default());
    let held2 = held.clone();
    tokio::spawn(async move {
        loop {
            let Ok((mut sck, _)) = hole.accept().await else {
                return;
            };
            let held = held2.clone();
            tokio::spawn(async move {
                use tokio::io::AsyncReadExt;
                let mut buf = [0u8; 4096];
                let _ = sck.read(&mut buf).await; // consume the request
                held.lock().unwrap().push(sck); // hold forever
            });
        }
    });
    state_b
        .peer
        .set_peer("inst-a", &format!("http://{hole_addr}"));

    // Two subscribers whose remote catch-up is blackholed.
    let mut s1 = lf_connect(addr_b, "xbh", "?cursor=beginning").await;
    let s2 = lf_connect(addr_b, "xbh", "?cursor=beginning").await;
    let (held_acc, eof) = hub_sse_collect(&mut s1, 2, |_| false).await;
    assert!(!eof, "a blackholed peer is a stall, not a disconnect");
    assert!(
        !held_acc.contains("event: data"),
        "no data while blackholed:\n{held_acc}"
    );
    assert!(
        held_acc.matches(": keep-alive").count() >= 3,
        "the BODY owns keep-alives — a blocked remote read must not \
         suppress them (got {}):\n{held_acc}",
        held_acc.matches(": keep-alive").count()
    );
    // One client's drop must not cancel the shared feed's work.
    drop(s2);
    let (still, eof2) = hub_sse_collect(&mut s1, 1, |_| false).await;
    assert!(!eof2, "the survivor stays open");
    assert!(
        still.matches(": keep-alive").count() >= 1,
        "still alive:\n{still}"
    );

    // Peer restored: recovery completes in place.
    state_b.peer.set_peer("inst-a", &format!("http://{addr_a}"));
    let (rec, eof3) = hub_sse_collect(&mut s1, 30, |t| lf_record_and_status(t, "\"h\":1")).await;
    assert!(!eof3, "recovery in place:\n{rec}");
    for i in 0..2u64 {
        let needle = format!("\"h\":{i}");
        assert_eq!(rec.matches(&needle).count(), 1, "{needle} once:\n{rec}");
    }
    // Final drop tears the feed down and CANCELS in-flight work.
    drop(s1);
    for _ in 0..200 {
        if state_b.livefeed.registry().len() == 0 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    }
    assert_eq!(
        state_b.livefeed.registry().len(),
        0,
        "teardown reaches zero feeds"
    );
}

/// Round-11.1 (red): a delayed seal publication over a parked FAN-OUT
/// creates ONE feed retry task, never a per-session timer herd — and
/// still converges promptly on release.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_seal_retry_is_one_task_per_feed_at_fanout() {
    let _serial = gap_lock().lock().await; // global failpoint registry
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfherd",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfherd", r#"{"s":0}"#).await;
    // The RetryLater window needs a SPLIT topology: a single-segment
    // close resolves as genuine closure without any retry.
    split_and_await(&state, "lfherd", 0).await;
    hub_append_lf(addr, "lfherd", r#"{"s":1}"#).await;
    let mut subs = Vec::new();
    for _ in 0..24 {
        let mut sck = lf_connect(addr, "lfherd", "").await;
        let (a, _) = hub_sse_collect(&mut sck, 8, |t| lf_record_and_status(t, "\"s\":1")).await;
        assert!(a.contains("upToDate"), "parked:\n{a}");
        subs.push(sck);
    }
    crate::failpoints::stop_before_sealed_publish("lfherd");
    let (st, _, _) = preq(
        addr,
        "POST",
        "/v1/streams/lfherd:seal",
        &[("prisma-encryption-key", PRISMA_KEY)],
        b"{}",
    )
    .await;
    assert!(st == 500 || st == 503, "withheld publication: {st}");
    // Let the withheld window breathe: every parked session wakes on
    // the close notify and observes the unresolved transition.
    tokio::time::sleep(std::time::Duration::from_millis(1200)).await;
    let key = crate::sse::session::feed_key_of(
        &state
            .registry
            .get(&state.deployment.raw_adapter_sref("lfherd"))
            .await
            .unwrap()
            .unwrap(),
        &Some(String::new()),
    );
    let feed = state
        .livefeed
        .registry()
        .feed_for_test(&key)
        .expect("shared feed");
    let spawns = feed.retry_spawns.load(std::sync::atomic::Ordering::Relaxed);
    assert!(
        (1..=3).contains(&spawns),
        "ONE retry scheduler per feed (a few re-arms tolerated), got {spawns} for 24 sessions"
    );
    crate::failpoints::stop_before_sealed_publish_off("lfherd");
    seal_ok(addr, "lfherd").await;
    let mut stuck = Vec::new();
    for (n, mut sck) in subs.into_iter().enumerate() {
        let (tail, eof) = hub_sse_collect(&mut sck, 5, |_| false).await;
        if !(eof && tail.matches("\"sealed\":true").count() == 1) {
            stuck.push((n, eof, tail.matches("\"sealed\":true").count()));
        }
    }
    assert!(
        stuck.is_empty(),
        "stuck subs {stuck:?}; feed={:?}",
        state.livefeed.registry().feed_for_test(&key).map(|f| (
            f.subscriber_count(),
            f.lifecycle_for_test(),
            f.current_source().closed(),
        )),
    );
}

/// Round-10 review: the per-RECORD payload ceiling is independent of
/// the request-body ceiling — a batch of many small records passes
/// while ONE record over the ceiling is refused 413, on both the
/// plain-append and the create-with-content paths.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn record_ceiling_refuses_one_oversized_record_not_the_batch() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    state.admission.set_record_ceiling(4096);
    let ct = [("content-type", "application/json")];
    // A JSON stream on the raw surface: appended ARRAYS split into
    // individual records, so the per-record ceiling is observable.
    let (st, _, _) = hreq(addr, "PUT", "/v1/stream/ceil", &ct, b"").await;
    assert!(st == 200 || st == 201, "create {st}");
    // A batch of MANY small records whose TOTAL far exceeds the
    // per-record ceiling: admitted (the ceiling is per record, never
    // per body).
    let batch: Vec<String> = (0..8)
        .map(|i| format!(r#"{{"i":{i},"pad":"{}"}}"#, "x".repeat(1024)))
        .collect();
    let (st, _, dbg) = hreq(
        addr,
        "POST",
        "/v1/stream/ceil",
        &ct,
        format!("[{}]", batch.join(",")).as_bytes(),
    )
    .await;
    assert!(
        st == 200 || st == 204,
        "a small-record batch passes: {st} {}",
        String::from_utf8_lossy(&dbg)
    );
    // ONE record over the ceiling: typed 413.
    let big = format!(r#"{{"big":"{}"}}"#, "y".repeat(8 * 1024));
    let (st, _, body) = hreq(addr, "POST", "/v1/stream/ceil", &ct, big.as_bytes()).await;
    assert_eq!(st, 413, "one oversized record is refused");
    assert!(
        String::from_utf8_lossy(&body).contains("record_too_large"),
        "typed refusal:\n{}",
        String::from_utf8_lossy(&body)
    );
    // A small record alongside one oversized record: the whole append
    // is refused (no partial admission).
    let mixed = format!(r#"[{{"ok":1}},{big}]"#);
    let (st, _, _) = hreq(addr, "POST", "/v1/stream/ceil", &ct, mixed.as_bytes()).await;
    assert_eq!(st, 413, "no partial admission of a mixed batch");
    // The PRODUCT surface treats the append body as ONE record: the
    // same oversized body is refused there too (the product error
    // translator renders the 413 as its generic body_too_large).
    let (st, _, _) = preq(
        addr,
        "POST",
        "/v1/streams/ceil/records",
        &[("prisma-encryption-key", PRISMA_KEY)],
        big.as_bytes(),
    )
    .await;
    assert_eq!(
        st, 413,
        "the product surface enforces the ceiling per body-record"
    );
    // Create-with-content enforces the same ceiling.
    let (st, _, body) = hreq(addr, "PUT", "/v1/stream/ceil2", &ct, big.as_bytes()).await;
    assert_eq!(st, 413, "create-with-content enforces the ceiling");
    assert!(
        String::from_utf8_lossy(&body).contains("record_too_large"),
        "typed refusal on create-with-content:\n{}",
        String::from_utf8_lossy(&body)
    );
}

/// Round-10 review reopen (red): PROJECT ISOLATION of the feed
/// retention budget. The process budget is a CELL safety ceiling —
/// one noisy project consuming it must not force an unrelated,
/// quota-respecting project's healthy subscribers into the uncached
/// reconnect posture. Noisy project A fills the (shrunk) global
/// budget with real retained rings across many two-subscriber
/// streams; victim project B then publishes on its own stream: B's
/// subscribers must receive the record IN PLACE — no EOF, no lag
/// disconnect. Multitenancy contract: only the offending project is
/// constrained.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_budget_noisy_project_cannot_evict_another() {
    let (svc, state, addr) = auth_rig("proj-noisy", "ws_iso", &["ca"], None).await;
    // Second project in the same cell: republish policies + grants at
    // v2 carrying BOTH projects (an omission would kill proj-noisy via
    // the high-water rules).
    {
        let mut projects = std::collections::HashMap::new();
        for p in ["proj-noisy", "proj-victim"] {
            let pol = rig_policy(p, "ws_iso", 1, 1);
            projects.insert(pol.project_id.clone(), pol);
        }
        svc.publish_policies(crate::project_policy::PolicySnapshot {
            projects,
            fetched_at_unix: crate::shard::now_ms() / 1000,
            feed_version: 2,
        })
        .unwrap();
        let mut credentials = std::collections::HashMap::new();
        for (cred, proj) in [("ca", "proj-noisy"), ("cb", "proj-victim")] {
            credentials.insert(
                std::sync::Arc::from(cred),
                crate::project_policy::CredentialGrant {
                    credential_id: std::sync::Arc::from(cred),
                    project_id: crate::tenant::ProjectId::new(proj).unwrap(),
                    grant_version: 1,
                    status: crate::project_policy::CredentialStatus::Active,
                    scopes: crate::tenant::ScopeSet::parse(RIG_SCOPES).0,
                    grant: crate::tenant::StreamGrant::All,
                    expires_at: None,
                },
            );
        }
        svc.publish_grants(crate::project_policy::GrantSnapshot {
            credentials,
            fetched_at_unix: crate::shard::now_ms() / 1000,
            feed_version: 2,
        })
        .unwrap();
    }
    // Cheap exhaustion geometry: 32-KiB rings under a 256-KiB cell
    // ceiling — twelve noisy feeds demand ~384 KiB of retention.
    state.livefeed.set_ring_bytes(32 * 1024);
    state.livefeed.budget().set_max_for_test(256 * 1024);
    let tok_a = mint_token("ca", "proj-noisy", "ws_iso", 1, 1, "na", 600);
    let tok_b = mint_token("cb", "proj-victim", "ws_iso", 1, 1, "vb", 600);

    // Noisy project A: 12 two-subscriber streams, rings filled with
    // real retained batches (8-KiB payloads; ~11-KiB prepared charge).
    let payload_a = format!(r#"{{"fill":"{}"}}"#, "a".repeat(8 * 1024));
    let mut noisy_subs = Vec::new();
    for s in 0..12 {
        let name = format!("na{s}");
        rig_create(addr, &name, &tok_a).await;
        for _ in 0..2 {
            let mut sck = rig_sse(addr, &name, &tok_a, "", None).await;
            let (acc, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
            assert!(acc.contains("upToDate"));
            noisy_subs.push(sck);
        }
        for _ in 0..4 {
            assert_eq!(rig_append(addr, &name, &tok_a, &payload_a).await, 200);
        }
    }
    // Let the noisy drives settle: the reserved gauge quiesces once
    // every publication decided its retention posture.
    let mut last = u64::MAX;
    for _ in 0..100 {
        let now = state.livefeed.budget().reserved();
        if now == last {
            break;
        }
        last = now;
        tokio::time::sleep(std::time::Duration::from_millis(150)).await;
    }

    // Victim project B: one stream, two healthy parked subscribers.
    rig_create(addr, "vb", &tok_b).await;
    let mut v1 = rig_sse(addr, "vb", &tok_b, "", None).await;
    let (b1, _) = hub_sse_collect(&mut v1, 8, |t| t.contains("upToDate")).await;
    assert!(b1.contains("upToDate"));
    let mut v2 = rig_sse(addr, "vb", &tok_b, "", None).await;
    let (b2, _) = hub_sse_collect(&mut v2, 8, |t| t.contains("upToDate")).await;
    assert!(b2.contains("upToDate"));
    // B publishes one 16-KiB record.
    let payload_b = format!(r#"{{"victim":"{}"}}"#, "b".repeat(16 * 1024));
    assert_eq!(rig_append(addr, "vb", &tok_b, &payload_b).await, 200);
    for (n, v) in [(1, &mut v1), (2, &mut v2)] {
        let (acc, eof) =
            hub_sse_collect(v, 10, |t| lf_record_and_status(t, "\"victim\":\"bb")).await;
        assert!(
            !eof,
            "victim sub{n}: a NOISY NEIGHBOR forced an unrelated project's \
             subscriber into the reconnect posture:\n…{}",
            &acc[acc.len().saturating_sub(400)..]
        );
        assert_eq!(
            acc.matches("\"victim\":\"").count(),
            1,
            "victim sub{n}: the record arrives in place exactly once"
        );
    }
}

/// Replaces `hub_delayed_reader_lands_on_the_current_scan_head`:
/// foreign-key appends advance a lane's scanned position without
/// delivering records; a DELAYED reader of the same lane must
/// converge to exactly the cursor the live subscriber holds.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_delayed_reader_lands_on_the_current_scan_head() {
    let store = mem();
    let (_state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfdr",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let mut s1 = lf_connect(addr, "lfdr", "?routingKey=ka").await;
    let (a, _) = hub_sse_collect(&mut s1, 8, |t| t.contains("upToDate")).await;
    assert!(a.contains("upToDate"));
    // Foreign-lane appends: the ka lane's scan head advances with NO
    // ka records.
    for i in 0..3 {
        let (st, _, _) = preq(
            addr,
            "POST",
            "/v1/streams/lfdr/records",
            &[
                ("prisma-encryption-key", PRISMA_KEY),
                ("prisma-routing-key", "other"),
            ],
            format!(r#"{{"f":{i}}}"#).as_bytes(),
        )
        .await;
        assert!(st == 200 || st == 204, "foreign append {st}");
    }
    // Drain to QUIESCENCE, not to the first control: the session may
    // emit an intermediate upToDate between the three appends on a
    // slow runner, and grabbing that cursor races the scan head (CI
    // flake at 11.6). All appends are durable before this collect, so
    // a bounded full drain always ends at the final head.
    let (live, eof) = hub_sse_collect(&mut s1, 3, |_| false).await;
    assert!(!eof, "foreign progress never disconnects:\n{live}");
    assert!(
        live.matches("\"upToDate\":true").count() >= 1 && live.contains("nextCursor"),
        "the live subscriber reports the advanced scan head:\n{live}"
    );
    assert!(
        !live.contains("\"f\":"),
        "foreign records must not cross lanes:\n{live}"
    );
    let live_cursor = last_next_cursor(&live);

    // The DELAYED reader of the same lane converges to the same head.
    let mut s2 = lf_connect(addr, "lfdr", "?routingKey=ka&cursor=beginning").await;
    let (d, eof2) = hub_sse_collect(&mut s2, 10, |t| t.contains("\"upToDate\":true")).await;
    assert!(!eof2);
    assert!(
        !d.contains("\"f\":"),
        "foreign records must not cross lanes:\n{d}"
    );
    assert_eq!(
        last_next_cursor(&d),
        live_cursor,
        "the delayed reader must land on the live subscriber's scan head:\n{d}"
    );
}

/// Replaces `hub_mass_disconnect_tears_down_within_deadline`: 20
/// LiveFeed subscribers dropped at once — connections AND feeds reach
/// zero within the teardown deadline (drop detaches; the last leave
/// evicts the feed).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_mass_disconnect_tears_down_within_deadline() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfmd",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfmd", r#"{"m":0}"#).await;
    let mut socks = Vec::new();
    for _ in 0..20 {
        let mut sck = lf_connect(addr, "lfmd", "").await;
        let (a, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
        assert!(a.contains("upToDate"));
        socks.push(sck);
    }
    assert!(
        state.livefeed.registry().len() >= 1,
        "the shared feed exists"
    );
    drop(socks);
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(3);
    loop {
        let conns = state.admission.snapshot().sse_connections;
        let feeds = state.livefeed.registry().len();
        if conns == 0 && feeds == 0 {
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "teardown deadline: conns={conns} feeds={feeds} after 3s"
        );
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }
}

/// 6.5: a split landing DURING initial catch-up — every record exactly
/// once, no disconnect (failpoint-parked between attach and start).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_split_during_initial_catchup_delivers_everything() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfc2",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    for i in 0..3u64 {
        hub_append_lf(addr, "lfc2", &format!(r#"{{"i":{i}}}"#)).await;
    }

    crate::failpoints::arm(crate::failpoints::Fp::SseFeedAfterSubscribe, "lfc2");
    let mut sck = lf_connect(addr, "lfc2", "?cursor=beginning").await;
    wait_parked(crate::failpoints::Fp::SseFeedAfterSubscribe, "lfc2", 1).await;

    // The split lands while the subscriber is parked between attach
    // and session start; successor records land after it.
    split_and_await(&state, "lfc2", 0).await;
    for i in 3..5u64 {
        hub_append_lf(addr, "lfc2", &format!(r#"{{"i":{i}}}"#)).await;
    }
    crate::failpoints::release(crate::failpoints::Fp::SseFeedAfterSubscribe, "lfc2");

    let (acc, eof) = hub_sse_collect(&mut sck, 12, |t| {
        t.matches("event: data").count() >= 5 && t.contains("upToDate")
    })
    .await;
    assert!(!eof, "no disconnect across the catch-up split:\n{acc}");
    for i in 0..5u64 {
        let needle = format!("\"i\":{i}}}");
        assert_eq!(
            acc.matches(&needle).count(),
            1,
            "record {i} exactly once across the split:\n{acc}"
        );
    }
    assert!(
        !acc.contains("\"sealed\":true"),
        "no false terminal control:\n{acc}"
    );
}

/// 6.5: a KEYED lane rides a split in place with its isolation intact.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_keyed_lane_survives_split() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfk2",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let mut sck = lf_connect(addr, "lfk2", "?routingKey=ka").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("upToDate"), "parks:\n{acc0}");

    split_and_await(&state, "lfk2", 0).await;

    // One record on the lane's key, one on a foreign key.
    for (k, v) in [("ka", 1), ("kb", 2)] {
        let (st, _, _) = preq(
            addr,
            "POST",
            "/v1/streams/lfk2/records",
            &[
                ("prisma-encryption-key", PRISMA_KEY),
                ("prisma-routing-key", k),
            ],
            format!(r#"{{"k":"{k}","v":{v}}}"#).as_bytes(),
        )
        .await;
        assert!(st == 200 || st == 204, "append {k}: {st}");
    }
    let (acc, eof) = hub_sse_collect(&mut sck, 10, |t| t.contains("\"v\":1")).await;
    assert!(!eof, "the keyed lane survives the split:\n{acc}");
    assert!(acc.contains("\"v\":1"), "lane record delivered:\n{acc}");
    assert!(
        !acc.contains("\"v\":2"),
        "foreign-key record must not cross the lane:\n{acc}"
    );
    assert!(
        !acc.contains("\"sealed\":true"),
        "no false terminal:\n{acc}"
    );
}

/// 6.4/6.5 fallback: the RAW surface takes the typed disconnect on a
/// split (scalar cursors cannot name segments) — EOF, never a
/// streamClosed.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_raw_disconnects_without_terminal_on_split() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let ct = ("content-type", "application/json");
    let (st, _, _) = hreq(addr, "PUT", "/v1/stream/lfr2", &[ct], br#"[{"r":0}]"#).await;
    assert!(st == 200 || st == 201);

    use tokio::io::AsyncWriteExt;
    let mut raw = tokio::net::TcpStream::connect(addr).await.unwrap();
    let start_tok = crate::offsets::encode_ep(0, crate::offsets::Offset::START);
    raw.write_all(
        format!(
            "GET /v1/stream/lfr2?live=sse&offset={start_tok} HTTP/1.1\r\nhost: x\r\ncontent-length: 0\r\nstream-encryption-key: {RIG_KEY_B64}\r\n\r\n"
        )
        .as_bytes(),
    )
    .await
    .unwrap();
    let (acc0, _) = hub_sse_collect(&mut raw, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("upToDate"), "raw parks:\n{acc0}");

    split_and_await(&state, "lfr2", 0).await;
    let (tail, eof) = hub_sse_collect(&mut raw, 12, |_| false).await;
    assert!(
        eof,
        "the raw session takes the typed disconnect; feeds={} tail:\n{tail}",
        state.livefeed.registry().len()
    );
    assert!(
        !tail.contains("\"streamClosed\":true"),
        "a topology fallback is NEVER a terminal control:\n{tail}"
    );
}

/// 6.5: two SEQUENTIAL splits continue in place — the source swaps
/// twice and every record lands exactly once.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_two_sequential_splits_continue_in_place() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfs3",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfs3", r#"{"i":0}"#).await;
    let mut sck = lf_connect(addr, "lfs3", "").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("\"i\":0"), "backlog:\n{acc0}");

    split_and_await(&state, "lfs3", 0).await;
    hub_append_lf(addr, "lfs3", r#"{"i":1}"#).await;
    let (acc1, eof1) = hub_sse_collect(&mut sck, 10, |t| t.contains("\"i\":1")).await;
    assert!(
        !eof1 && acc1.contains("\"i\":1"),
        "first swap delivers:\n{acc1}"
    );

    // The SECOND split, of the lane's current live segment.
    state
        .registry
        .invalidate(&state.deployment.raw_adapter_sref("lfs3"));
    let desc = state
        .registry
        .get(&state.deployment.raw_adapter_sref("lfs3"))
        .await
        .unwrap()
        .unwrap();
    let live_seg = desc.resolve_segment("").seg_id;
    split_and_await(&state, "lfs3", live_seg).await;
    hub_append_lf(addr, "lfs3", r#"{"i":2}"#).await;
    let (acc2, eof2) = hub_sse_collect(&mut sck, 12, |t| {
        t.contains("\"i\":2") && t.matches("\"upToDate\":true").count() >= 3
    })
    .await;
    assert!(!eof2, "the second swap must not disconnect either");
    let full = format!("{acc0}{acc1}{acc2}");
    for i in 0..3u64 {
        let needle = format!("\"i\":{i}}}");
        assert_eq!(
            full.matches(&needle).count(),
            1,
            "record {i} exactly once across two splits:\n{full}"
        );
    }
    assert!(
        !full.contains("\"sealed\":true"),
        "no false terminal across two splits:\n{full}"
    );
}

/// 6.5 lifecycle: delete + recreate is a DISTINCT incarnation — the
/// old feed never leaks new-incarnation records to the old session,
/// no terminal control is forged, and the recreated stream lands on a
/// FRESH feed (storage-hash feed identity). The old session itself
/// lingers until its lease/client closes, exactly like the legacy
/// path: nothing about a delete closes the old segment's handle, and
/// a key-leased session has no deadline pressure — what MUST hold is
/// that the incarnations share nothing.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_delete_recreate_isolates_incarnations() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfd",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    let mut sck = lf_connect(addr, "lfd", "").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("upToDate"), "parks:\n{acc0}");
    assert_eq!(
        state.livefeed.registry().len(),
        1,
        "one feed on the first incarnation"
    );

    let (st, _, _) = preq(
        addr,
        "DELETE",
        "/v1/streams/lfd",
        &[("prisma-encryption-key", PRISMA_KEY)],
        b"",
    )
    .await;
    assert!(st == 200 || st == 202 || st == 204, "delete {st}");

    // Recreate may briefly race deletion cleanup; the new incarnation
    // serves a fresh feed independently.
    let mut created = false;
    for _ in 0..50 {
        let (st, _, _) = preq(
            addr,
            "PUT",
            "/v1/streams/lfd",
            &[("prisma-encryption-key", PRISMA_KEY)],
            br#"{"format":{"kind":"json"}}"#,
        )
        .await;
        if st == 201 {
            created = true;
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    }
    assert!(created, "recreate");
    hub_append_lf(addr, "lfd", r#"{"n":1}"#).await;

    // The OLD session must NOT see the new incarnation's records (nor
    // any forged terminal): a short window with nothing new arriving.
    let (acc1, _) = hub_sse_collect(&mut sck, 4, |t| t.contains("\"n\":1")).await;
    assert!(
        !acc1.contains("\"n\":1"),
        "no cross-incarnation delivery to the old session:\n{acc1}"
    );
    assert!(
        !acc1.contains("\"sealed\":true"),
        "delete is never a terminal control:\n{acc1}"
    );

    // The recreated stream is a DISTINCT feed (storage-hash identity).
    let mut sck2 = lf_connect(addr, "lfd", "").await;
    let (acc2, _) = hub_sse_collect(&mut sck2, 8, |t| t.contains("\"n\":1")).await;
    assert!(
        acc2.contains("\"n\":1"),
        "the new incarnation serves normally:\n{acc2}"
    );
    assert_eq!(
        state.livefeed.registry().len(),
        2,
        "old and new incarnations are distinct feeds"
    );

    // Old session closes: its feed is evicted; the new one remains.
    drop(sck);
    for _ in 0..100 {
        if state.livefeed.registry().len() == 1 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
    assert_eq!(
        state.livefeed.registry().len(),
        1,
        "the old feed is evicted"
    );
}

// ==================================================================
// LIVE-FEED Stage 6 round-4 legs: wire-position correctness
// (decode-and-resume), shared-subscriber swap, and the deterministic
// seal-to-publication handoff.
// ==================================================================

/// Extract the LAST product nextCursor token from a transcript.
fn last_next_cursor(t: &str) -> String {
    let at = t.rfind("\"nextCursor\":\"").expect("a product cursor");
    let rest = &t[at + "\"nextCursor\":\"".len()..];
    rest.split('"').next().expect("cursor value").to_string()
}

/// LiveFeed collect stop: the successor record arrived AND the
/// standalone status control after it. LiveFeed record controls are
/// BARE (no flags) — a stop condition counting per-record `upToDate`
/// flags matches the LEGACY hub shape only and burns its entire
/// deadline on the LiveFeed engine (30 s of idle collect per
/// subscriber is exactly where loaded CI runners breed flakes).
fn lf_record_and_status(t: &str, needle: &str) -> bool {
    t.find(needle)
        .is_some_and(|at| t[at..].contains("\"upToDate\":true"))
}

/// Round-4 blocker 1 (red): the cursor emitted after a split must
/// name the successor segment AND the SEGMENT-LOCAL offset — and it
/// must be usable to resume with no gap and no duplicate.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_split_cursor_decodes_to_segment_local_and_resumes() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfcur",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    for i in 0..5u64 {
        hub_append_lf(addr, "lfcur", &format!(r#"{{"i":{i}}}"#)).await;
    }
    let mut sck = lf_connect(addr, "lfcur", "").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("\"i\":4"), "backlog:\n{acc0}");

    split_and_await(&state, "lfcur", 0).await;
    // The FIRST child record (child-local offset 0).
    hub_append_lf(addr, "lfcur", r#"{"i":5}"#).await;
    let (acc1, _) = hub_sse_collect(&mut sck, 10, |t| lf_record_and_status(t, "\"i\":5")).await;
    assert!(acc1.contains("\"i\":5"), "successor record:\n{acc1}");

    // Decode the cursor at the head: it must be (child, 1) — the
    // segment-local position after the first child record — never the
    // linearized stream offset (which would be 6).
    let tok = last_next_cursor(&acc1);
    state
        .registry
        .invalidate(&state.deployment.raw_adapter_sref("lfcur"));
    let desc = state
        .registry
        .get(&state.deployment.raw_adapter_sref("lfcur"))
        .await
        .unwrap()
        .unwrap();
    let epoch = desc.epoch_bytes().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    let expected = crate::product_cursor::KeyCursor {
        epoch,
        key_hash: crate::crypto::stream_hash(""),
        seg_id: child_seg,
        offset: 1,
    }
    .encode(&desc.project_id, &skey());
    assert_eq!(
        tok, expected,
        "the emitted cursor IS (successor segment, segment-local 1) —          never the linearized offset (6)"
    );

    // RESUME from the emitted cursor: append one more child record,
    // reconnect with the cursor, and require exactly the tail — no
    // gap, no duplicate. (The reconnect lands on the legacy lineage
    // path; the cursor contract is engine-independent.)
    hub_append_lf(addr, "lfcur", r#"{"i":6}"#).await;
    let mut sub2 = lf_connect(addr, "lfcur", &format!("?cursor={tok}")).await;
    let (acc2, _) = hub_sse_collect(&mut sub2, 10, |t| t.contains("\"i\":6")).await;
    assert!(
        acc2.contains("\"i\":6"),
        "resume must deliver the record AFTER the cursor:\n{acc2}"
    );
    assert!(
        !acc2.contains("\"i\":5"),
        "resume must not redeliver the cursor's own record:\n{acc2}"
    );
}

/// Round-4 blocker 2 (red): TWO shared subscribers, one swap — both
/// receive the successor record exactly once, and both head cursors
/// decode to the successor's segment-local position.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_split_shared_subscribers_swap_once_deliver_twice() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfsh",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfsh", r#"{"i":0}"#).await;
    let mut sub1 = lf_connect(addr, "lfsh", "").await;
    let (_, _) = hub_sse_collect(&mut sub1, 8, |t| t.contains("upToDate")).await;
    let mut sub2 = lf_connect(addr, "lfsh", "").await;
    let (_, _) = hub_sse_collect(&mut sub2, 8, |t| t.contains("upToDate")).await;

    split_and_await(&state, "lfsh", 0).await;
    hub_append_lf(addr, "lfsh", r#"{"i":1}"#).await;

    let mut curs = Vec::new();
    for (n, s) in [(1, &mut sub1), (2, &mut sub2)] {
        let (acc, eof) = hub_sse_collect(s, 30, |t| lf_record_and_status(t, "\"i\":1")).await;
        if eof {
            let topo = crate::sse::auth::sse_stats::FEED_TOPOLOGY_DISCONNECTS
                .load(std::sync::atomic::Ordering::Relaxed);
            let lag = crate::sse::auth::sse_stats::FEED_LAG_DISCONNECTS
                .load(std::sync::atomic::Ordering::Relaxed);
            let srcf = crate::sse::auth::sse_stats::FEED_SOURCE_FAILED
                .load(std::sync::atomic::Ordering::Relaxed);
            let retries = crate::sse::auth::sse_stats::FEED_CATCHUP_RETRIES
                .load(std::sync::atomic::Ordering::Relaxed);
            let feed_state = state
                .livefeed
                .registry()
                .feed_for_test(&crate::sse::session::feed_key_of(
                    &state
                        .registry
                        .get(&state.deployment.raw_adapter_sref("lfsh"))
                        .await
                        .unwrap()
                        .unwrap(),
                    &Some(String::new()),
                ))
                .map(|f| {
                    format!(
                        "subs={} head={} floor={} gen={} retained={}",
                        f.subscriber_count(),
                        f.head(),
                        f.floor(),
                        f.source_snapshot().generation,
                        f.retained()
                    )
                })
                .unwrap_or_else(|| "feed-gone".to_string());
            panic!(
                "sub{n} disconnected across the split: topo={topo} lag={lag} srcfailed={srcf} retries={retries} feed[{feed_state}]"
            );
        }
        assert_eq!(
            acc.matches("\"i\":1").count(),
            1,
            "sub{n}: successor record exactly once:\n{acc}"
        );
        assert!(
            !acc.contains("\"sealed\":true"),
            "sub{n}: no false terminal:\n{acc}"
        );
        curs.push(last_next_cursor(&acc));
    }

    state
        .registry
        .invalidate(&state.deployment.raw_adapter_sref("lfsh"));
    let desc = state
        .registry
        .get(&state.deployment.raw_adapter_sref("lfsh"))
        .await
        .unwrap()
        .unwrap();
    let epoch = desc.epoch_bytes().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    let expected = crate::product_cursor::KeyCursor {
        epoch,
        key_hash: crate::crypto::stream_hash(""),
        seg_id: child_seg,
        offset: 1,
    }
    .encode(&desc.project_id, &skey());
    for (n, tok) in curs.iter().enumerate() {
        assert_eq!(
            tok,
            &expected,
            "sub{}: cursor IS (successor segment, segment-local 1)",
            n + 1
        );
    }
}

/// Round-4 blocker 4 (red): the seal-to-publication handoff does NOT
/// depend on the heartbeat — with the successor publication HELD at a
/// failpoint, no false terminal appears; on release, the parked
/// session continues promptly (deadline well below the 15-s
/// heartbeat).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_split_held_publication_handoff_is_prompt() {
    let _gap = gap_lock().lock().await;
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfhp",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfhp", r#"{"i":0}"#).await;
    let mut sck = lf_connect(addr, "lfhp", "").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(acc0.contains("upToDate"), "parks:\n{acc0}");

    // Hold the successor publication AFTER the parent seal.
    crate::failpoints::arm_scaler_before_publish("lfhp");
    let guard = FailpointGuard("lfhp".to_string());
    let split = {
        let state = state.clone();
        tokio::spawn(async move {
            crate::scaler3::execute_split(
                &state,
                &state.deployment.raw_adapter_sref("lfhp"),
                0,
                0x8000_0000_0000_0000,
            )
            .await
        })
    };
    // Enter the gap: parent sealed, descriptor still pending.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
    loop {
        let d = state
            .registry
            .get(&state.deployment.raw_adapter_sref("lfhp"))
            .await
            .unwrap()
            .unwrap();
        if d.segments.as_ref().is_some_and(|m| m.pending.is_some()) {
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "seal gap never entered"
        );
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }

    // While the publication is held: no terminal control may appear.
    let (acc1, _) = hub_sse_collect(&mut sck, 3, |_| false).await;
    assert!(
        !acc1.contains("\"sealed\":true"),
        "no terminal while the transition is held:\n{acc1}"
    );

    // Release: the parked session must continue PROMPTLY (well below
    // the 15-s heartbeat that a detached-resume design would need).
    drop(guard);
    await_published(&state, "lfhp").await;
    hub_append_lf(addr, "lfhp", r#"{"i":1}"#).await;
    let t0 = std::time::Instant::now();
    let (acc2, _) = hub_sse_collect(&mut sck, 5, |t| t.contains("\"i\":1")).await;
    assert!(
        acc2.contains("\"i\":1"),
        "successor record arrives promptly after publication:\n{acc2}"
    );
    assert!(
        t0.elapsed() < std::time::Duration::from_secs(10),
        "delivery must not wait for the heartbeat"
    );
    assert!(
        !acc2.contains("\"sealed\":true"),
        "no false terminal after the handoff:\n{acc2}"
    );
    let _ = split.await;
}

// ==================================================================
// LIVE-FEED Stage 6 round-5 legs: seal-before-refresh drain,
// raw late-attach compatibility, external adoption custody.
// ==================================================================

/// Round-5 blocker 1 (red): split + successor records + seal ALL
/// before the session refreshes — the session must drain the full
/// successor lineage FIRST, then emit exactly one terminal control.
/// With TWO shared subscribers.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_split_seal_before_refresh_drains_then_terminates() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfseal",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    for i in 0..2u64 {
        hub_append_lf(addr, "lfseal", &format!(r#"{{"i":{i}}}"#)).await;
    }
    let mut sub1 = lf_connect(addr, "lfseal", "").await;
    let (_, _) = hub_sse_collect(&mut sub1, 8, |t| t.contains("upToDate")).await;
    let mut sub2 = lf_connect(addr, "lfseal", "").await;
    let (_, _) = hub_sse_collect(&mut sub2, 8, |t| t.contains("upToDate")).await;

    // Hold BOTH subscribers' drives, then: split, append successor
    // records, seal the collection — ALL before any refresh. Wait for
    // both sessions to actually PARK at the drive failpoint first
    // (round 6: the intended interleaving must be reached every run).
    crate::failpoints::arm(crate::failpoints::Fp::SseFeedBeforeDrive, "lfseal");
    split_and_await(&state, "lfseal", 0).await;
    wait_parked(crate::failpoints::Fp::SseFeedBeforeDrive, "lfseal", 2).await;
    for i in 2..4u64 {
        hub_append_lf(addr, "lfseal", &format!(r#"{{"i":{i}}}"#)).await;
    }
    seal_ok(addr, "lfseal").await;
    crate::failpoints::release(crate::failpoints::Fp::SseFeedBeforeDrive, "lfseal");

    // Both subscribers: all four records exactly once, then ONE
    // terminal control, then EOF — and the TERMINAL cursor names the
    // final segment-local position.
    state
        .registry
        .invalidate(&state.deployment.raw_adapter_sref("lfseal"));
    let desc = state
        .registry
        .get(&state.deployment.raw_adapter_sref("lfseal"))
        .await
        .unwrap()
        .unwrap();
    let epoch = desc.epoch_bytes().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    let expected_terminal = crate::product_cursor::KeyCursor {
        epoch,
        key_hash: crate::crypto::stream_hash(""),
        seg_id: child_seg,
        offset: 2,
    }
    .encode(&desc.project_id, &skey());
    for (n, s) in [(1, &mut sub1), (2, &mut sub2)] {
        let (acc, eof) = hub_sse_collect(s, 15, |_| false).await;
        assert!(eof, "sub{n}: EOF after the terminal control");
        // The subscribers joined at Now: the SUCCESSOR records are
        // what the drain must not lose.
        for i in 2..4u64 {
            let needle = format!("\"i\":{i}}}");
            assert_eq!(
                acc.matches(&needle).count(),
                1,
                "sub{n}: successor record {i} exactly once (no drain loss):\n{acc}"
            );
        }
        assert_eq!(
            acc.matches("\"sealed\":true").count(),
            1,
            "sub{n}: exactly one terminal control:\n{acc}"
        );
        assert_eq!(
            last_next_cursor(&acc),
            expected_terminal,
            "sub{n}: the terminal cursor IS (successor segment, segment-local 2)"
        );
    }
}

/// Round-5 blocker 3 (red): a RAW request that attaches AFTER the
/// lane's feed swapped takes the typed fallback — immediate EOF,
/// never a scalar control over lineage data, never a terminal.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_raw_late_attach_after_swap_gets_no_lineage_scalars() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let ct = ("content-type", "application/json");
    let (st, _, _) = hreq(addr, "PUT", "/v1/stream/lfr3", &[ct], br#"[{"r":0}]"#).await;
    assert!(st == 200 || st == 201);

    // A PRODUCT subscriber holds the default lane's feed.
    let mut prod = lf_connect(addr, "lfr3", "").await;
    let (_, _) = hub_sse_collect(&mut prod, 8, |t| t.contains("upToDate")).await;

    // The raw request parks BEFORE the lease gate (thus before attach).
    crate::failpoints::arm(crate::failpoints::Fp::SseBeforeLeaseGate, "lfr3");
    use tokio::io::AsyncWriteExt;
    let mut raw = tokio::net::TcpStream::connect(addr).await.unwrap();
    let start_tok = crate::offsets::encode_ep(0, crate::offsets::Offset::START);
    raw.write_all(
        format!(
            "GET /v1/stream/lfr3?live=sse&offset={start_tok} HTTP/1.1\r\nhost: x\r\ncontent-length: 0\r\nstream-encryption-key: {RIG_KEY_B64}\r\n\r\n"
        )
        .as_bytes(),
    )
    .await
    .unwrap();
    wait_parked(crate::failpoints::Fp::SseBeforeLeaseGate, "lfr3", 1).await;

    // Split + successor append: the PRODUCT session swaps the feed to
    // a lineage source (generation 1).
    split_and_await(&state, "lfr3", 0).await;
    hub_append_lf(addr, "lfr3", r#"{"r":1}"#).await;
    let (p1, _) = hub_sse_collect(&mut prod, 10, |t| t.contains("\"r\":1")).await;
    assert!(p1.contains("\"r\":1"), "product rode the swap:\n{p1}");

    // Resume the raw request: it must NOT emit the successor record
    // with scalar controls — typed immediate disconnect only.
    crate::failpoints::release(crate::failpoints::Fp::SseBeforeLeaseGate, "lfr3");
    let (acc, eof) = hub_sse_collect(&mut raw, 10, |_| false).await;
    assert!(
        eof,
        "the late-attaching raw request is cut off, not served lineage"
    );
    assert!(
        !acc.contains("\"streamClosed\":true"),
        "the fallback is never a terminal control:\n{acc}"
    );
    assert!(
        !acc.contains("\"r\":1"),
        "no successor data with scalar cursors:\n{acc}"
    );
}

/// Round-5/6 blocker 2 (red): the child engine LiveFeed opens for a
/// swapped lineage carries the EXTERNAL adoption stamp FROM THE
/// LIVEFEED BUILD ITSELF — no customer request ever touches the empty
/// successor (round-6 correction: the old version appended first,
/// which itself stamped the engine and masked the implementation).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_swap_externally_adopts_child_engines() {
    let _serial = sweep_lock().lock().await;
    let store = mem();
    let prefixes = vec![
        "00".to_string(),
        "01".to_string(),
        "10".to_string(),
        "11".to_string(),
    ];
    let (state, addr) = http_rig_cold_absorb(store, prefixes.clone()).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfad",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfad", r#"{"i":0}"#).await;
    let mut sck = lf_connect(addr, "lfad", "").await;
    let (_, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;

    split_and_await(&state, "lfad", 0).await;

    // Wait for LiveFeed to observe the sealed parent and build/install
    // the EMPTY child lineage (feed generation 1). No customer request
    // has touched the child.
    state
        .registry
        .invalidate(&state.deployment.raw_adapter_sref("lfad"));
    let desc = state
        .registry
        .get(&state.deployment.raw_adapter_sref("lfad"))
        .await
        .unwrap()
        .unwrap();
    let fkey = crate::sse::session::feed_key_of(&desc, &Some(String::new()));
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
    loop {
        let g = state
            .livefeed
            .registry()
            .feed_for_test(&fkey)
            .map(|f| f.source_snapshot().generation);
        if g == Some(1) {
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "the feed never swapped to the lineage source (gen={g:?})"
        );
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }

    // The child engine must carry the external adoption stamp from the
    // LiveFeed build (last_external_seq > 0), and sweeps must neither
    // close it nor install custody.
    let child_route = desc.segment_route_by_id(desc.resolve_segment("").seg_id);
    let prefix = state.shards.prefix_for(&child_route);
    let engine = state
        .shards
        .open(&prefix)
        .expect("the child engine is resident after the swap");
    assert!(
        engine
            .last_external_seq
            .load(std::sync::atomic::Ordering::Relaxed)
            > 0,
        "the LiveFeed build itself must stamp external adoption — no customer request touched the child"
    );
    for _ in 0..6 {
        crate::billing::sweep_owned_outboxes(&state).await;
    }
    assert!(
        state.shards.is_open(&prefix),
        "an engine serving a customer LiveFeed must never be sweep-closed"
    );
    assert_eq!(
        engine
            .sweep_custody
            .load(std::sync::atomic::Ordering::Relaxed),
        0,
        "custody must never be installed over a customer LiveFeed engine"
    );

    // And delivery through the swapped source still works.
    hub_append_lf(addr, "lfad", r#"{"i":1}"#).await;
    let (acc, _) = hub_sse_collect(&mut sck, 10, |t| t.contains("\"i\":1")).await;
    assert!(acc.contains("\"i\":1"), "the swap delivered:\n{acc}");
}

/// Round-6 raw gate second level (red): the swap lands BETWEEN the
/// compatibility peek and the atomic attach — the atomically captured
/// join generation (not the peek) is what must refuse the raw session.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_raw_swap_between_peek_and_attach_is_refused() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let ct = ("content-type", "application/json");
    let (st, _, _) = hreq(addr, "PUT", "/v1/stream/lfr5", &[ct], br#"[{"r":0}]"#).await;
    assert!(st == 200 || st == 201);

    // A PRODUCT subscriber holds the default lane's feed (generation 0,
    // so the peek would PASS for a raw request).
    let mut prod = lf_connect(addr, "lfr5", "").await;
    let (_, _) = hub_sse_collect(&mut prod, 8, |t| t.contains("upToDate")).await;

    // The raw request parks AFTER the peek, BEFORE the attach.
    crate::failpoints::arm(crate::failpoints::Fp::SseFeedBeforeSubscribe, "lfr5");
    use tokio::io::AsyncWriteExt;
    let mut raw = tokio::net::TcpStream::connect(addr).await.unwrap();
    let start_tok = crate::offsets::encode_ep(0, crate::offsets::Offset::START);
    raw.write_all(
        format!(
            "GET /v1/stream/lfr5?live=sse&offset={start_tok} HTTP/1.1\r\nhost: x\r\ncontent-length: 0\r\nstream-encryption-key: {RIG_KEY_B64}\r\n\r\n"
        )
        .as_bytes(),
    )
    .await
    .unwrap();
    wait_parked(crate::failpoints::Fp::SseFeedBeforeSubscribe, "lfr5", 1).await;

    // Split + successor append: the PRODUCT session swaps the feed to
    // generation 1 in the window between peek and attach.
    split_and_await(&state, "lfr5", 0).await;
    hub_append_lf(addr, "lfr5", r#"{"r":1}"#).await;
    let (p1, _) = hub_sse_collect(&mut prod, 10, |t| t.contains("\"r\":1")).await;
    assert!(p1.contains("\"r\":1"), "product rode the swap:\n{p1}");

    // Resume the raw request: the ATOMIC attach captures generation 1
    // and the raw session is refused — immediate EOF, never scalar
    // lineage data, never a terminal control.
    crate::failpoints::release(crate::failpoints::Fp::SseFeedBeforeSubscribe, "lfr5");
    let (acc, eof) = hub_sse_collect(&mut raw, 10, |_| false).await;
    assert!(
        eof,
        "the raw request attaching to a swapped feed is refused"
    );
    assert!(
        !acc.contains("\"streamClosed\":true"),
        "the refusal is never a terminal control:\n{acc}"
    );
    assert!(
        !acc.contains("\"r\":1"),
        "no successor data with scalar cursors:\n{acc}"
    );
}

/// Round-6 refresh regression (red): a transition completed EXTERNALLY
/// must be picked up by a later refresh with a stale descriptor and
/// signature — the unconditional re-read installs the lineage (the
/// resume boolean is never treated as evidence of no change).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_refresh_installs_after_external_completion() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let (st, _, _) = preq(
        addr,
        "PUT",
        "/v1/streams/lfx5",
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    hub_append_lf(addr, "lfx5", r#"{"i":0}"#).await;

    // Capture the PRE-SPLIT descriptor, then complete the split
    // EXTERNALLY (no LiveFeed involvement).
    let old_desc = state
        .registry
        .get(&state.deployment.raw_adapter_sref("lfx5"))
        .await
        .unwrap()
        .unwrap();
    split_and_await(&state, "lfx5", 0).await;

    // Refresh with the stale descriptor + old span signature: the
    // re-read must install the longer compatible lineage.
    let epoch = old_desc.epoch_bytes().unwrap();
    let outcome = crate::sse::source::refresh_transition(
        &state,
        &old_desc,
        &skey(),
        &epoch,
        &Some(String::new()),
        &[(0, 0, None)],
    )
    .await
    .unwrap();
    match outcome {
        crate::sse::feed::SourceTransition::NewSource(src) => {
            let sig = src.span_sig();
            assert_eq!(sig.len(), 2, "the refreshed lineage has both spans");
            assert_eq!(sig[0], (0, 0, Some(1)), "the parent gained its cap");
            assert_eq!(sig[1].1, 1, "the successor starts at the cap");
        }
        _ => panic!("refresh after external completion must install the lineage"),
    }
}

// ==================================================================
// LIVE-FEED Stage 7A legs: connect-time product lineage. A stream
// ALREADY split when the request arrives builds a LineageSource at
// connect and rides the same engine — beginning, now, signed cursors
// in every span position, invalid cursors, and sealed streams.
// ==================================================================

/// Create a stream, append records, split, append more — return the
/// post-split descriptor.
async fn lf7_split_stream(
    addr: std::net::SocketAddr,
    state: &Arc<crate::http::AppState>,
    name: &str,
    pre: u64,
    post: u64,
) -> crate::registry::StreamDesc {
    let (st, _, _) = preq(
        addr,
        "PUT",
        &format!("/v1/streams/{name}"),
        &[("prisma-encryption-key", PRISMA_KEY)],
        br#"{"format":{"kind":"json"}}"#,
    )
    .await;
    assert_eq!(st, 201);
    for i in 0..pre {
        hub_append_lf(addr, name, &format!(r#"{{"i":{i}}}"#)).await;
    }
    split_and_await(state, name, 0).await;
    for i in pre..(pre + post) {
        hub_append_lf(addr, name, &format!(r#"{{"i":{i}}}"#)).await;
    }
    state
        .registry
        .invalidate(&state.deployment.raw_adapter_sref(name));
    state
        .registry
        .get(&state.deployment.raw_adapter_sref(name))
        .await
        .unwrap()
        .unwrap()
}

/// Connect at `cursor=beginning` on an ALREADY-split stream: the full
/// lineage (predecessor + successor) drains through LiveFeed.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_connect_already_split_beginning_drains_lineage() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let _ = lf7_split_stream(addr, &state, "lf7b", 3, 2).await;

    let mut sck = lf_connect(addr, "lf7b", "?cursor=beginning").await;
    let (acc, _) = hub_sse_collect(&mut sck, 12, |t| {
        t.matches("event: data").count() >= 5 && t.contains("upToDate")
    })
    .await;
    for i in 0..5u64 {
        let needle = format!("\"i\":{i}}}");
        assert_eq!(
            acc.matches(&needle).count(),
            1,
            "record {i} exactly once through connect-time lineage:\n{acc}"
        );
    }
    assert!(acc.contains("upToDate"), "reached the head:\n{acc}");

    // And live records keep flowing on the same connection.
    hub_append_lf(addr, "lf7b", r#"{"i":5}"#).await;
    let (acc2, _) = hub_sse_collect(&mut sck, 10, |t| t.contains("\"i\":5")).await;
    assert!(acc2.contains("\"i\":5"), "live records flow:\n{acc2}");
}

/// Connect at `cursor=now` on an already-split stream: only records
/// written after the connect arrive.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_connect_already_split_now() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let _ = lf7_split_stream(addr, &state, "lf7n", 3, 2).await;

    let mut sck = lf_connect(addr, "lf7n", "?cursor=now").await;
    let (acc0, _) = hub_sse_collect(&mut sck, 8, |t| t.contains("upToDate")).await;
    assert!(
        !acc0.contains("event: data"),
        "now starts at the tail:\n{acc0}"
    );
    hub_append_lf(addr, "lf7n", r#"{"i":5}"#).await;
    let (acc, _) = hub_sse_collect(&mut sck, 10, |t| t.contains("\"i\":5")).await;
    assert!(acc.contains("\"i\":5"), "only post-connect records:\n{acc}");
    assert!(!acc.contains("\"i\":4"), "no history:\n{acc}");
}

/// Connect with a SIGNED cursor inside a sealed predecessor: the
/// predecessor remainder plus the successor tail arrive exactly once.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_connect_already_split_cursor_in_sealed_predecessor() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let desc = lf7_split_stream(addr, &state, "lf7p", 3, 2).await;
    let epoch = desc.epoch_bytes().unwrap();

    // Cursor: consumed through predecessor record 1 (local offset 2).
    let tok = crate::product_cursor::KeyCursor {
        epoch,
        key_hash: crate::crypto::stream_hash(""),
        seg_id: 0,
        offset: 2,
    }
    .encode(&desc.project_id, &skey());
    let mut sck = lf_connect(addr, "lf7p", &format!("?cursor={tok}")).await;
    let (acc, _) = hub_sse_collect(&mut sck, 12, |t| {
        t.matches("event: data").count() >= 3 && t.contains("upToDate")
    })
    .await;
    for i in [2u64, 3, 4] {
        let needle = format!("\"i\":{i}}}");
        assert_eq!(
            acc.matches(&needle).count(),
            1,
            "record {i} exactly once from the predecessor cursor:\n{acc}"
        );
    }
    assert!(
        !acc.contains("\"i\":0") && !acc.contains("\"i\":1"),
        "records at/below the cursor are not redelivered:\n{acc}"
    );
}

/// Connect with a signed cursor in the live tail and exactly at a span
/// boundary; a cursor beyond a sealed cap is a 400; an unknown segment
/// is a 400.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_connect_already_split_cursor_positions() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let desc = lf7_split_stream(addr, &state, "lf7c", 3, 2).await;
    let epoch = desc.epoch_bytes().unwrap();
    let child_seg = desc.resolve_segment("").seg_id;
    let mk = |seg_id: u32, offset: u64| {
        crate::product_cursor::KeyCursor {
            epoch,
            key_hash: crate::crypto::stream_hash(""),
            seg_id,
            offset,
        }
        .encode(&desc.project_id, &skey())
    };

    // In the live tail (child, 0): only successor records.
    let mut s1 = lf_connect(addr, "lf7c", &format!("?cursor={}", mk(child_seg, 0))).await;
    let (a1, _) = hub_sse_collect(&mut s1, 10, |t| t.matches("event: data").count() >= 2).await;
    assert!(
        a1.contains("\"i\":3") && a1.contains("\"i\":4"),
        "live tail:\n{a1}"
    );
    assert!(
        !a1.contains("\"i\":2"),
        "no predecessor records from a tail cursor:\n{a1}"
    );

    // Exactly at the span boundary (seg 0, cap): continues into the
    // successor with no gap and no duplicate.
    let mut s2 = lf_connect(addr, "lf7c", &format!("?cursor={}", mk(0, 3))).await;
    let (a2, _) = hub_sse_collect(&mut s2, 10, |t| t.matches("event: data").count() >= 2).await;
    assert!(
        a2.contains("\"i\":3") && a2.contains("\"i\":4"),
        "boundary resumes into the successor:\n{a2}"
    );
    assert!(
        !a2.contains("\"i\":2"),
        "no duplicate at the boundary:\n{a2}"
    );

    // Beyond the sealed cap: 400.
    let (st, _, _) = preq(
        addr,
        "GET",
        &format!("/v1/streams/lf7c/records:sse?cursor={}", mk(0, 99)),
        &[("prisma-encryption-key", PRISMA_KEY)],
        b"",
    )
    .await;
    assert_eq!(st, 400, "beyond a sealed cap is invalid_cursor");

    // Unknown segment: 400.
    let (st, _, _) = preq(
        addr,
        "GET",
        &format!("/v1/streams/lf7c/records:sse?cursor={}", mk(77, 0)),
        &[("prisma-encryption-key", PRISMA_KEY)],
        b"",
    )
    .await;
    assert_eq!(st, 400, "an unknown segment is invalid_cursor");
}

/// Connect at beginning on a SEALED split stream: full lineage, then
/// exactly one terminal control, then EOF.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn livefeed_connect_already_split_sealed_stream() {
    let store = mem();
    let (state, addr) = http_rig(store).await;
    let _ = lf7_split_stream(addr, &state, "lf7s", 3, 2).await;
    seal_ok(addr, "lf7s").await;

    let mut sck = lf_connect(addr, "lf7s", "?cursor=beginning").await;
    let (acc, eof) = hub_sse_collect(&mut sck, 15, |_| false).await;
    assert!(eof, "EOF after the terminal");
    for i in 0..5u64 {
        let needle = format!("\"i\":{i}}}");
        assert_eq!(
            acc.matches(&needle).count(),
            1,
            "record {i} exactly once on the sealed stream:\n{acc}"
        );
    }
    assert_eq!(
        acc.matches("\"sealed\":true").count(),
        1,
        "exactly one terminal control:\n{acc}"
    );
}

